	        if \(!initialized_\) \{
	            initialized_ = true;
	            max_seq_ = seq;
	            r.updated = true;
	            r.ext_seq = seq;
	            return r;
	        \}

	        if \(seq < max_seq_ && \(max_seq_ - seq\) > 0x8000\) \{
	            cycles_ \+= 0x10000ULL;
	        \}

	        if \(seq > max_seq_ && \(seq - max_seq_\) < 0x8000\) \{
	            max_seq_ = seq;
	        \}

	        r.updated = true;
	        r.ext_seq = cycles_ \+ seq;
	        return r;
	    \}/	    result update(std::uint16_t seq) {
	        result r{};

	        if (!initialized_) {
	            initialized_ = true;
	            max_seq_ = seq;
	            r.updated = true;
	            r.ext_seq = seq;
	            return r;
	        }

	        std::uint64_t seq_cycles = cycles_;

	        if (seq < max_seq_) {
	            if ((max_seq_ - seq) > 0x8000) {
	                cycles_ += 0x10000ULL;
	                seq_cycles = cycles_;
	                max_seq_ = seq;
	            }
	        }
	        else if (seq > max_seq_) {
	            if ((seq - max_seq_) < 0x8000) {
	                max_seq_ = seq;
	            }
	            else if (cycles_ >= 0x10000ULL) {
	                seq_cycles = cycles_ - 0x10000ULL;
	            }
	        }

	        r.updated = true;
	        r.ext_seq = seq_cycles + seq;
	        return r;
	    }/s

