+}
+
+struct udp_rtp_sender {
+    int fd{-1};
+    sockaddr_in addr{};
+
+    std::uint32_t ssrc{0};
+    std::uint8_t pt{33};
+    std::uint16_t seq{0};
+    std::uint32_t timestamp{0};
+
+    std::size_t payload_size{1316};
+    bool mpegts_payload{false};
+
+    bool open(const std::string& ip, std::uint16_t port) {
+        fd = ::socket(AF_INET, SOCK_DGRAM, 0);
+        if (fd < 0) {
+            perror("socket");
+            return false;
+        }
+
+        std::memset(&addr, 0, sizeof(addr));
+        addr.sin_family = AF_INET;
+        addr.sin_port = htons(port);
+
+        if (::inet_pton(AF_INET, ip.c_str(), &addr.sin_addr) != 1) {
+            std::cerr << "invalid ip: " << ip << "\n";
+            return false;
+        }
+
+        return true;
+    }
+
+    void close() {
+        if (fd >= 0) {
+            ::close(fd);
+            fd = -1;
+        }
+    }
+
+    void make_packet(std::vector<std::uint8_t>& out) {
+        out.resize(12 + payload_size);
+
+        out[0] = 0x80;
+        out[1] = pt & 0x7f;
+
+        put_u16_be(&out[2], seq);
+        put_u32_be(&out[4], timestamp);
+        put_u32_be(&out[8], ssrc);
+
+        auto* payload = out.data() + 12;
+
+        if (mpegts_payload) {
+            for (std::size_t i = 0; i < payload_size; ++i) {
+                payload[i] = (i % 188 == 0)
+                    ? 0x47
+                    : static_cast<std::uint8_t>((seq + i) & 0xff);
+            }
+        } else {
+            for (std::size_t i = 0; i < payload_size; ++i) {
+                payload[i] = static_cast<std::uint8_t>((seq + i) & 0xff);
+            }
+        }
+    }
+
+    void send_packet(const std::vector<std::uint8_t>& packet) {
+        const auto n = ::sendto(
+            fd,
+            packet.data(),
+            packet.size(),
+            0,
+            reinterpret_cast<const sockaddr*>(&addr),
+            sizeof(addr));
+
+        if (n < 0) {
+            perror("sendto");
+        }
+    }
+};
+
+struct fec_state {
+    std::vector<std::uint8_t> row_xor;
+    std::vector<std::uint8_t> col_xor;
+
+    std::uint32_t row_count{0};
+    std::uint32_t col_count{0};
+};
+
+void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
+    const std::size_t header_size = 12;
+    const std::size_t payload_size = rtp_packet.size() - header_size;
+
+    if (acc.empty()) {
+        acc.assign(payload_size, 0);
+    }
+
+    for (std::size_t i = 0; i < payload_size; ++i) {
+        acc[i] ^= rtp_packet[header_size + i];
+    }
+}
+
+void make_fec_payload_packet(
+    udp_rtp_sender& fec_sender,
+    const std::vector<std::uint8_t>& xor_payload_data,
+    std::vector<std::uint8_t>& out)
+{
+    fec_sender.payload_size = xor_payload_data.size();
+    fec_sender.make_packet(out);
+
+    std::memcpy(out.data() + 12, xor_payload_data.data(), xor_payload_data.size());
+}
+
+void run_rtp(const options& opt) {
+    const double packets_per_sec =
+        static_cast<double>(opt.bitrate_bps) /
+        static_cast<double>(opt.payload_size * 8);
+
+    if (packets_per_sec <= 0.0) {
+        std::cerr << "invalid packets_per_sec\n";
+        return;
+    }
+
+    const auto interval = std::chrono::nanoseconds(
+        static_cast<long long>(1'000'000'000.0 / packets_per_sec));
+
+    const std::uint32_t ts_step =
+        static_cast<std::uint32_t>(
+            static_cast<double>(opt.clock_rate) / packets_per_sec);
+
+    udp_rtp_sender media;
+    media.ssrc = opt.ssrc;
+    media.pt = opt.pt;
+    media.payload_size = opt.payload_size;
+    media.mpegts_payload = opt.mpegts_payload;
+
+    if (!media.open(opt.dst, opt.port)) {
+        return;
+    }
+
+    udp_rtp_sender fec_row;
+    udp_rtp_sender fec_col;
+
+    if (opt.fec) {
+        fec_row.ssrc = opt.fec_row_ssrc;
+        fec_row.pt = opt.fec_pt;
+        fec_row.payload_size = opt.payload_size;
+
+        fec_col.ssrc = opt.fec_col_ssrc;
+        fec_col.pt = opt.fec_pt;
+        fec_col.payload_size = opt.payload_size;
+
+        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
+            return;
+        }
+        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
+            return;
+        }
+    }
+
+    std::cerr
+        << "RTP media: " << opt.dst << ":" << opt.port
+        << " ssrc=" << opt.ssrc
+        << " pt=" << static_cast<int>(opt.pt)
+        << " bitrate=" << opt.bitrate_bps
+        << " payload=" << opt.payload_size
+        << " pps=" << packets_per_sec
+        << "\n";
+
+    if (opt.fec) {
+        std::cerr
+            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
+            << " ssrc=" << opt.fec_row_ssrc
+            << " pt=" << static_cast<int>(opt.fec_pt)
+            << " L=" << opt.fec_l
+            << "\n";
+
+        std::cerr
+            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
+            << " ssrc=" << opt.fec_col_ssrc
+            << " pt=" << static_cast<int>(opt.fec_pt)
+            << " D=" << opt.fec_d
+            << "\n";
+    }
+
+    std::mt19937 rng{std::random_device{}()};
+    std::uniform_real_distribution<double> dist{0.0, 1.0};
+
+    std::vector<std::uint8_t> media_packet;
+    std::vector<std::uint8_t> delayed_packet;
+    bool has_delayed_packet = false;
+
+    fec_state fec;
+    std::vector<std::uint8_t> fec_packet;
+
+    auto next = clock_type::now();
+
+    while (!g_stop) {
+        if (has_delayed_packet) {
+            media.send_packet(delayed_packet);
+            has_delayed_packet = false;
+        }
+
+        media.make_packet(media_packet);
+
+        if (opt.fec) {
+            xor_payload(fec.row_xor, media_packet);
+            xor_payload(fec.col_xor, media_packet);
+
+            ++fec.row_count;
+            ++fec.col_count;
+
+            if (fec.row_count >= opt.fec_l) {
+                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
+                fec_row.send_packet(fec_packet);
+                ++fec_row.seq;
+                fec_row.timestamp += ts_step * opt.fec_l;
+
+                fec.row_xor.clear();
+                fec.row_count = 0;
+            }
+
+            if (fec.col_count >= opt.fec_d) {
+                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
+                fec_col.send_packet(fec_packet);
+                ++fec_col.seq;
+                fec_col.timestamp += ts_step * opt.fec_d;
+
+                fec.col_xor.clear();
+                fec.col_count = 0;
+            }
+        }
+
+        const bool drop = dist(rng) < opt.loss_rate;
+        const bool duplicate = dist(rng) < opt.duplicate_rate;
+        const bool reorder = dist(rng) < opt.reorder_rate;
+
+        if (!drop) {
+            if (reorder && !has_delayed_packet) {
+                delayed_packet = media_packet;
+                has_delayed_packet = true;
+            } else {
+                media.send_packet(media_packet);
+            }
+
+            if (duplicate) {
+                media.send_packet(media_packet);
+            }
+        }
+
+        ++media.seq;
+        media.timestamp += ts_step;
+
+        next += interval;
+        std::this_thread::sleep_until(next);
+    }
+
+    media.close();
+
+    if (opt.fec) {
+        fec_row.close();
+        fec_col.close();
+    }
+}
+
+void run_srt(const options& opt) {
+#ifndef ENABLE_SRT
+    std::cerr << "SRT disabled. Build with -DENABLE_SRT and link libsrt.\n";
+    (void)opt;
+#else
+    SRTSOCKET sock = srt_create_socket();
+    if (sock == SRT_INVALID_SOCK) {
+        std::cerr << "srt_create_socket failed\n";
+        return;
+    }
+
+    int yes = 1;
+    srt_setsockopt(sock, 0, SRTO_SENDER, &yes, sizeof(yes));
+
+    sockaddr_in sa{};
+    sa.sin_family = AF_INET;
+    sa.sin_port = htons(opt.port);
+
+    if (::inet_pton(AF_INET, opt.dst.c_str(), &sa.sin_addr) != 1) {
+        std::cerr << "invalid ip: " << opt.dst << "\n";
+        srt_close(sock);
+        return;
