460	void apply_mcast_options(udp_rtp_sender& s, const options& opt) {
461	    s.mcast_if = opt.mcast_if;
462	    s.mcast_ttl = opt.mcast_ttl;
463	    s.mcast_loop = opt.mcast_loop;
464	}
