644	void run_srt(const options& opt) {
645	#ifndef ENABLE_SRT
646	    std::cerr << "SRT disabled. Build with -DENABLE_SRT and link libsrt.\n";
647	    (void)opt;
648	#else
649	    SRTSOCKET sock = srt_create_socket();
650	    if (sock == SRT_INVALID_SOCK) {
651	        std::cerr << "srt_create_socket failed\n";
652	        return;
653	    }
654	
655	    int yes = 1;
656	    srt_setsockopt(sock, 0, SRTO_SENDER, &yes, sizeof(yes));
657	
658	    sockaddr_in sa{};
659	    sa.sin_family = AF_INET;
660	    sa.sin_port = htons(opt.port);
661	
662	    if (::inet_pton(AF_INET, opt.dst.c_str(), &sa.sin_addr) != 1) {
663	        std::cerr << "invalid ip: " << opt.dst << "\n";
664	        srt_close(sock);
665	        return;
666	    }
667	
668	    if (srt_connect(sock, reinterpret_cast<sockaddr*>(&sa), sizeof(sa)) == SRT_ERROR) {
669	        std::cerr << "srt_connect failed: " << srt_getlasterror_str() << "\n";
670	        srt_close(sock);
671	        return;
672	    }
673	
674	    const double packets_per_sec =
675	        static_cast<double>(opt.bitrate_bps) /
676	        static_cast<double>(opt.payload_size * 8);
677	
678	    if (packets_per_sec <= 0.0) {
679	        std::cerr << "invalid SRT packets_per_sec\n";
680	        srt_close(sock);
681	        return;
682	    }
683	
684	    const auto interval = std::chrono::nanoseconds(
685	        static_cast<long long>(1'000'000'000.0 / packets_per_sec));
686	
687	    std::vector<char> payload(opt.payload_size, 0);
688	
689	    std::cerr
690	        << "SRT: " << opt.dst << ":" << opt.port
691	        << " bitrate=" << opt.bitrate_bps
692	        << " payload=" << opt.payload_size
693	        << " pps=" << packets_per_sec
694	        << "\n";
695	
696	    auto next = clock_type::now();
697	    std::uint64_t counter = 0;
698	
699	    while (!g_stop) {
700	        for (std::size_t i = 0; i < payload.size(); ++i) {
701	            payload[i] = static_cast<char>((counter + i) & 0xff);
702	        }
703	
704	        const int ret = srt_sendmsg(
705	            sock,
706	            payload.data(),
707	            static_cast<int>(payload.size()),
708	            -1,
709	            0);
710	
711	        if (ret == SRT_ERROR) {
712	            std::cerr << "srt_sendmsg failed: " << srt_getlasterror_str() << "\n";
713	            break;
714	        }
715	
716	        ++counter;
717	
718	        next += interval;
719	        std::this_thread::sleep_until(next);
720	    }
721	
722	    srt_close(sock);
723	#endif
724	}
