301	struct udp_rtp_sender {
302	    int fd{-1};
303	    sockaddr_in addr{};
304	
305	    std::uint32_t ssrc{0};
306	    std::uint8_t pt{33};
307	    std::uint16_t seq{0};
308	    std::uint32_t timestamp{0};
309	
310	    std::size_t payload_size{1316};
311	    bool mpegts_payload{false};
312	
313	    std::string mcast_if{};
314	    int mcast_ttl{1};
315	    int mcast_loop{1};
316	
317	    bool open(const std::string& ip, std::uint16_t port) {
318	        fd = ::socket(AF_INET, SOCK_DGRAM, 0);
319	        if (fd < 0) {
320	            perror("socket");
321	            return false;
322	        }
323	
324	        std::memset(&addr, 0, sizeof(addr));
325	        addr.sin_family = AF_INET;
326	        addr.sin_port = htons(port);
327	
328	        if (::inet_pton(AF_INET, ip.c_str(), &addr.sin_addr) != 1) {
329	            std::cerr << "invalid ip: " << ip << "\n";
330	            return false;
331	        }
332	
333	        if (is_ipv4_multicast_addr(addr.sin_addr)) {
334	            if (!configure_multicast()) {
335	                return false;
336	            }
337	        }
338	
339	        return true;
340	    }
341	
342	    bool configure_multicast() {
343	        const unsigned char ttl = static_cast<unsigned char>(mcast_ttl);
344	        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
345	            perror("setsockopt IP_MULTICAST_TTL");
346	            return false;
347	        }
348	
349	        const unsigned char loop = static_cast<unsigned char>(mcast_loop != 0);
350	        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_LOOP, &loop, sizeof(loop)) < 0) {
351	            perror("setsockopt IP_MULTICAST_LOOP");
352	            return false;
353	        }
354	
355	        if (!mcast_if.empty()) {
356	            in_addr local_if{};
357	            if (::inet_pton(AF_INET, mcast_if.c_str(), &local_if) != 1) {
358	                std::cerr << "invalid --mcast-if: " << mcast_if << "\n";
359	                return false;
360	            }
361	
362	            if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_IF, &local_if, sizeof(local_if)) < 0) {
363	                perror("setsockopt IP_MULTICAST_IF");
364	                return false;
365	            }
366	        }
367	
368	        return true;
369	    }
370	
371	    void close() {
372	        if (fd >= 0) {
373	            ::close(fd);
374	            fd = -1;
375	        }
376	    }
377	
378	    void make_packet(std::vector<std::uint8_t>& out) {
379	        out.resize(12 + payload_size);
380	
381	        out[0] = 0x80;          // V=2, P=0, X=0, CC=0
382	        out[1] = pt & 0x7f;     // M=0, PT
383	
384	        put_u16_be(&out[2], seq);
385	        put_u32_be(&out[4], timestamp);
386	        put_u32_be(&out[8], ssrc);
387	
388	        auto* payload = out.data() + 12;
389	
390	        if (mpegts_payload) {
391	            // MPEG-TS風ダミーpayload。
392	            // 188 byteごとにsync byte 0x47を置くだけなので、再生可能なTSではない。
393	            for (std::size_t i = 0; i < payload_size; ++i) {
394	                payload[i] = (i % 188 == 0)
395	                    ? 0x47
396	                    : static_cast<std::uint8_t>((seq + i) & 0xff);
397	            }
398	        } else {
399	            for (std::size_t i = 0; i < payload_size; ++i) {
400	                payload[i] = static_cast<std::uint8_t>((seq + i) & 0xff);
401	            }
402	        }
403	    }
404	
405	    void send_packet(const std::vector<std::uint8_t>& packet) {
406	        const auto n = ::sendto(
407	            fd,
408	            packet.data(),
409	            packet.size(),
410	            0,
411	            reinterpret_cast<const sockaddr*>(&addr),
412	            sizeof(addr));
413	
414	        if (n < 0) {
415	            perror("sendto");
416	        }
417	    }
418	};
419	
420	struct fec_state {
421	    std::vector<std::uint8_t> row_xor;
422	    std::vector<std::uint8_t> col_xor;
423	
424	    std::uint32_t row_count{0};
425	    std::uint32_t col_count{0};
426	};
427	
428	void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
429	    constexpr std::size_t header_size = 12;
430	
431	    if (rtp_packet.size() < header_size) {
432	        return;
433	    }
434	
435	    const std::size_t payload_len = rtp_packet.size() - header_size;
436	
437	    if (acc.empty()) {
438	        acc.assign(payload_len, 0);
439	    }
440	
441	    const auto n = std::min(acc.size(), payload_len);
442	    for (std::size_t i = 0; i < n; ++i) {
443	        acc[i] ^= rtp_packet[header_size + i];
444	    }
445	}
446	
447	void make_fec_payload_packet(
448	    udp_rtp_sender& fec_sender,
449	    const std::vector<std::uint8_t>& xor_payload_data,
450	    std::vector<std::uint8_t>& out)
451	{
452	    fec_sender.payload_size = xor_payload_data.size();
453	    fec_sender.make_packet(out);
454	
455	    if (!xor_payload_data.empty()) {
456	        std::memcpy(out.data() + 12, xor_payload_data.data(), xor_payload_data.size());
457	    }
458	}
459	
460	void apply_mcast_options(udp_rtp_sender& s, const options& opt) {
461	    s.mcast_if = opt.mcast_if;
462	    s.mcast_ttl = opt.mcast_ttl;
463	    s.mcast_loop = opt.mcast_loop;
464	}
465	
466	void run_rtp(const options& opt) {
467	    const double packets_per_sec =
468	        static_cast<double>(opt.bitrate_bps) /
469	        static_cast<double>(opt.payload_size * 8);
470	
471	    if (packets_per_sec <= 0.0) {
472	        std::cerr << "invalid packets_per_sec\n";
473	        return;
474	    }
475	
476	    const auto interval = std::chrono::nanoseconds(
477	        static_cast<long long>(1'000'000'000.0 / packets_per_sec));
478	
479	    const std::uint32_t ts_step =
480	        static_cast<std::uint32_t>(
481	            static_cast<double>(opt.clock_rate) / packets_per_sec);
482	
483	    udp_rtp_sender media;
484	    media.ssrc = opt.ssrc;
485	    media.pt = opt.pt;
486	    media.payload_size = opt.payload_size;
487	    media.mpegts_payload = opt.mpegts_payload;
488	    apply_mcast_options(media, opt);
489	
490	    if (!media.open(opt.dst, opt.port)) {
491	        return;
492	    }
493	
494	    udp_rtp_sender fec_row;
495	    udp_rtp_sender fec_col;
496	
497	    if (opt.fec) {
498	        fec_row.ssrc = opt.fec_row_ssrc;
499	        fec_row.pt = opt.fec_pt;
500	        fec_row.payload_size = opt.payload_size;
501	        fec_row.mpegts_payload = false;
502	        apply_mcast_options(fec_row, opt);
503	
504	        fec_col.ssrc = opt.fec_col_ssrc;
505	        fec_col.pt = opt.fec_pt;
506	        fec_col.payload_size = opt.payload_size;
507	        fec_col.mpegts_payload = false;
508	        apply_mcast_options(fec_col, opt);
509	
510	        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
511	            media.close();
512	            return;
513	        }
514	
515	        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
516	            media.close();
517	            fec_row.close();
518	            return;
519	        }
520	    }
521	
522	    std::cerr
523	        << "RTP media: " << opt.dst << ":" << opt.port
524	        << " ssrc=" << opt.ssrc
525	        << " pt=" << static_cast<int>(opt.pt)
526	        << " bitrate=" << opt.bitrate_bps
527	        << " payload=" << opt.payload_size
528	        << " pps=" << packets_per_sec
529	        << " ts_step=" << ts_step
530	        << "\n";
531	
532	    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
533	        std::cerr
534	            << "multicast: ttl=" << opt.mcast_ttl
535	            << " loop=" << opt.mcast_loop;
536	
537	        if (!opt.mcast_if.empty()) {
538	            std::cerr << " if=" << opt.mcast_if;
539	        } else {
540	            std::cerr << " if=<route-default>";
541	        }
542	
543	        std::cerr << "\n";
544	    }
545	
546	    if (opt.fec) {
547	        std::cerr
548	            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
549	            << " ssrc=" << opt.fec_row_ssrc
550	            << " pt=" << static_cast<int>(opt.fec_pt)
551	            << " L=" << opt.fec_l
552	            << "\n";
553	
554	        std::cerr
555	            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
556	            << " ssrc=" << opt.fec_col_ssrc
557	            << " pt=" << static_cast<int>(opt.fec_pt)
558	            << " D=" << opt.fec_d
559	            << "\n";
560	    }
561	
562	    std::mt19937 rng{std::random_device{}()};
563	    std::uniform_real_distribution<double> dist{0.0, 1.0};
564	
565	    std::vector<std::uint8_t> media_packet;
566	    std::vector<std::uint8_t> delayed_packet;
567	    bool has_delayed_packet = false;
568	
569	    fec_state fec;
570	    std::vector<std::uint8_t> fec_packet;
571	
572	    auto next = clock_type::now();
573	
574	    while (!g_stop) {
575	        if (has_delayed_packet) {
576	            media.send_packet(delayed_packet);
577	            has_delayed_packet = false;
578	        }
579	
580	        media.make_packet(media_packet);
581	
582	        if (opt.fec) {
583	            xor_payload(fec.row_xor, media_packet);
584	            xor_payload(fec.col_xor, media_packet);
585	
586	            ++fec.row_count;
587	            ++fec.col_count;
588	
589	            if (fec.row_count >= opt.fec_l) {
590	                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
591	                fec_row.send_packet(fec_packet);
592	
593	                ++fec_row.seq;
594	                fec_row.timestamp += ts_step * opt.fec_l;
595	
596	                fec.row_xor.clear();
597	                fec.row_count = 0;
598	            }
599	
600	            if (fec.col_count >= opt.fec_d) {
601	                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
602	                fec_col.send_packet(fec_packet);
603	
604	                ++fec_col.seq;
605	                fec_col.timestamp += ts_step * opt.fec_d;
606	
607	                fec.col_xor.clear();
608	                fec.col_count = 0;
609	            }
610	        }
611	
612	        const bool drop = dist(rng) < opt.loss_rate;
613	        const bool duplicate = dist(rng) < opt.duplicate_rate;
614	        const bool reorder = dist(rng) < opt.reorder_rate;
615	
616	        if (!drop) {
617	            if (reorder && !has_delayed_packet) {
618	                delayed_packet = media_packet;
619	                has_delayed_packet = true;
620	            } else {
621	                media.send_packet(media_packet);
622	            }
623	
624	            if (duplicate) {
625	                media.send_packet(media_packet);
626	            }
627	        }
628	
629	        ++media.seq;
630	        media.timestamp += ts_step;
631	
632	        next += interval;
633	        std::this_thread::sleep_until(next);
634	    }
635	
636	    media.close();
637	
638	    if (opt.fec) {
639	        fec_row.close();
640	        fec_col.close();
641	    }
642	}
643	
644	void run_srt(const options& opt) {
645	#ifndef ENABLE_SRT
646	    std::cerr << "SRT disabled. Build with -DENABLE_SRT and link libsrt.\n";
647	    (void)opt;
648	#else
649	    SRTSOCKET sock = srt_create_socket();
650	    if (sock == SRT_INVALID_SOCK) {
651	        std::cerr << "srt_create_socket failed\n";
652	        return;
653	    }
654	
655	    int yes = 1;
656	    srt_setsockopt(sock, 0, SRTO_SENDER, &yes, sizeof(yes));
657	
658	    sockaddr_in sa{};
659	    sa.sin_family = AF_INET;
660	    sa.sin_port = htons(opt.port);
661	
662	    if (::inet_pton(AF_INET, opt.dst.c_str(), &sa.sin_addr) != 1) {
663	        std::cerr << "invalid ip: " << opt.dst << "\n";
664	        srt_close(sock);
665	        return;
666	    }
667	
668	    if (srt_connect(sock, reinterpret_cast<sockaddr*>(&sa), sizeof(sa)) == SRT_ERROR) {
669	        std::cerr << "srt_connect failed: " << srt_getlasterror_str() << "\n";
670	        srt_close(sock);
671	        return;
672	    }
673	
674	    const double packets_per_sec =
675	        static_cast<double>(opt.bitrate_bps) /
676	        static_cast<double>(opt.payload_size * 8);
677	
678	    if (packets_per_sec <= 0.0) {
679	        std::cerr << "invalid SRT packets_per_sec\n";
680	        srt_close(sock);
681	        return;
682	    }
683	
684	    const auto interval = std::chrono::nanoseconds(
685	        static_cast<long long>(1'000'000'000.0 / packets_per_sec));
686	
687	    std::vector<char> payload(opt.payload_size, 0);
688	
689	    std::cerr
690	        << "SRT: " << opt.dst << ":" << opt.port
691	        << " bitrate=" << opt.bitrate_bps
692	        << " payload=" << opt.payload_size
693	        << " pps=" << packets_per_sec
694	        << "\n";
695	
696	    auto next = clock_type::now();
697	    std::uint64_t counter = 0;
698	
699	    while (!g_stop) {
700	        for (std::size_t i = 0; i < payload.size(); ++i) {
701	            payload[i] = static_cast<char>((counter + i) & 0xff);
702	        }
703	
704	        const int ret = srt_sendmsg(
705	            sock,
706	            payload.data(),
707	            static_cast<int>(payload.size()),
708	            -1,
709	            0);
710	
711	        if (ret == SRT_ERROR) {
712	            std::cerr << "srt_sendmsg failed: " << srt_getlasterror_str() << "\n";
713	            break;
714	        }
715	
716	        ++counter;
717	
718	        next += interval;
719	        std::this_thread::sleep_until(next);
720	    }
721	
722	    srt_close(sock);
723	#endif
724	}
725	
726	} // namespace
727	
728	int main(int argc, char** argv) {
729	    std::signal(SIGINT, on_signal);
730	    std::signal(SIGTERM, on_signal);
731	
732	    const auto parsed = parse_args(argc, argv);
733	    if (!parsed) {
734	        usage(argv[0]);
735	        return 1;
736	    }
737	
738	    const auto& opt = *parsed;
739	
740	#ifdef ENABLE_SRT
741	    srt_startup();
742	#endif
743	
744	    switch (opt.proto) {
745	    case proto_type::rtp:
746	        run_rtp(opt);
747	        break;
748	    case proto_type::srt:
749	        run_srt(opt);
750	        break;
751	    }
752	
753	#ifdef ENABLE_SRT
754	    srt_cleanup();
755	#endif
756	
757	    return 0;
758	}

