 79	    std::uint32_t fec_row_ssrc{2001};
 80	    std::uint32_t fec_col_ssrc{2002};
 81	
 82	    // 簡易FEC用。厳密なRFC/SMPTE準拠ではない。
 83	    std::uint32_t fec_l{4};
 84	    std::uint32_t fec_d{4};
 85	
 86	    // IPv4 multicast送信用オプション。
 87	    // --dst が 224.0.0.0/4 の場合に適用される。
 88	    std::string mcast_if{};
 89	    int mcast_ttl{1};
 90	    int mcast_loop{1};
 91	};
