 93	std::uint16_t parse_u16(const char* s, const char* name) {
 94	    const auto v = std::stoul(s);
 95	    if (v > 65535) {
 96	        throw std::runtime_error(std::string(name) + " out of range: " + s);
 97	    }
 98	    return static_cast<std::uint16_t>(v);
 99	}
100	
101	std::uint8_t parse_u8(const char* s, const char* name) {
102	    const auto v = std::stoul(s);
103	    if (v > 255) {
104	        throw std::runtime_error(std::string(name) + " out of range: " + s);
105	    }
106	    return static_cast<std::uint8_t>(v);
107	}
