153	std::optional<options> parse_args(int argc, char** argv) {
154	    options opt;
155	
156	    try {
157	        for (int i = 1; i < argc; ++i) {
158	            std::string a = argv[i];
159	
160	            auto next = [&](const char* name) -> const char* {
161	                if (!need_value(i, argc, name)) {
162	                    return nullptr;
163	                }
164	                return argv[++i];
165	            };
166	
167	            if (a == "--proto") {
168	                const char* v = next("--proto");
169	                if (!v) return std::nullopt;
170	
171	                std::string s = v;
172	                if (s == "rtp") {
173	                    opt.proto = proto_type::rtp;
174	                } else if (s == "srt") {
175	                    opt.proto = proto_type::srt;
176	                } else {
177	                    std::cerr << "invalid proto: " << s << "\n";
178	                    return std::nullopt;
179	                }
180	            } else if (a == "--dst") {
181	                const char* v = next("--dst");
182	                if (!v) return std::nullopt;
183	                opt.dst = v;
184	            } else if (a == "--port") {
185	                const char* v = next("--port");
186	                if (!v) return std::nullopt;
187	                opt.port = parse_u16(v, "--port");
188	            } else if (a == "--bitrate") {
189	                const char* v = next("--bitrate");
190	                if (!v) return std::nullopt;
191	                opt.bitrate_bps = static_cast<std::uint32_t>(std::stoul(v));
192	            } else if (a == "--payload-size") {
193	                const char* v = next("--payload-size");
194	                if (!v) return std::nullopt;
195	                opt.payload_size = static_cast<std::size_t>(std::stoull(v));
196	            } else if (a == "--ssrc") {
197	                const char* v = next("--ssrc");
198	                if (!v) return std::nullopt;
199	                opt.ssrc = static_cast<std::uint32_t>(std::stoul(v));
200	            } else if (a == "--pt") {
201	                const char* v = next("--pt");
202	                if (!v) return std::nullopt;
203	                opt.pt = parse_u8(v, "--pt");
204	            } else if (a == "--clock-rate") {
205	                const char* v = next("--clock-rate");
206	                if (!v) return std::nullopt;
207	                opt.clock_rate = static_cast<std::uint32_t>(std::stoul(v));
208	            } else if (a == "--mpegts-payload") {
209	                const char* v = next("--mpegts-payload");
210	                if (!v) return std::nullopt;
211	                opt.mpegts_payload = std::stoul(v) != 0;
212	            } else if (a == "--loss") {
213	                const char* v = next("--loss");
214	                if (!v) return std::nullopt;
215	                opt.loss_rate = std::stod(v);
216	            } else if (a == "--duplicate") {
217	                const char* v = next("--duplicate");
218	                if (!v) return std::nullopt;
219	                opt.duplicate_rate = std::stod(v);
220	            } else if (a == "--reorder") {
221	                const char* v = next("--reorder");
222	                if (!v) return std::nullopt;
223	                opt.reorder_rate = std::stod(v);
224	            } else if (a == "--fec") {
225	                opt.fec = true;
226	            } else if (a == "--fec-row-port") {
227	                const char* v = next("--fec-row-port");
228	                if (!v) return std::nullopt;
229	                opt.fec_row_port = parse_u16(v, "--fec-row-port");
230	            } else if (a == "--fec-col-port") {
231	                const char* v = next("--fec-col-port");
232	                if (!v) return std::nullopt;
233	                opt.fec_col_port = parse_u16(v, "--fec-col-port");
234	            } else if (a == "--fec-pt") {
235	                const char* v = next("--fec-pt");
236	                if (!v) return std::nullopt;
237	                opt.fec_pt = parse_u8(v, "--fec-pt");
238	            } else if (a == "--fec-row-ssrc") {
239	                const char* v = next("--fec-row-ssrc");
240	                if (!v) return std::nullopt;
241	                opt.fec_row_ssrc = static_cast<std::uint32_t>(std::stoul(v));
242	            } else if (a == "--fec-col-ssrc") {
243	                const char* v = next("--fec-col-ssrc");
244	                if (!v) return std::nullopt;
245	                opt.fec_col_ssrc = static_cast<std::uint32_t>(std::stoul(v));
246	            } else if (a == "--fec-l") {
247	                const char* v = next("--fec-l");
248	                if (!v) return std::nullopt;
249	                opt.fec_l = static_cast<std::uint32_t>(std::stoul(v));
250	            } else if (a == "--fec-d") {
251	                const char* v = next("--fec-d");
252	                if (!v) return std::nullopt;
253	                opt.fec_d = static_cast<std::uint32_t>(std::stoul(v));
254	            } else if (a == "--mcast-if") {
255	                const char* v = next("--mcast-if");
256	                if (!v) return std::nullopt;
257	                opt.mcast_if = v;
258	            } else if (a == "--mcast-ttl") {
259	                const char* v = next("--mcast-ttl");
260	                if (!v) return std::nullopt;
261	                opt.mcast_ttl = std::stoi(v);
262	            } else if (a == "--mcast-loop") {
263	                const char* v = next("--mcast-loop");
264	                if (!v) return std::nullopt;
265	                opt.mcast_loop = std::stoi(v);
266	            } else if (a == "--help" || a == "-h") {
267	                return std::nullopt;
268	            } else {
269	                std::cerr << "unknown option: " << a << "\n";
270	                return std::nullopt;
271	            }
272	        }
273	    } catch (const std::exception& e) {
274	        std::cerr << "argument parse error: " << e.what() << "\n";
275	        return std::nullopt;
276	    }
277	
278	    if (opt.payload_size == 0) {
279	        std::cerr << "--payload-size must be greater than 0\n";
280	        return std::nullopt;
281	    }
282	
283	    if (opt.bitrate_bps == 0) {
284	        std::cerr << "--bitrate must be greater than 0\n";
285	        return std::nullopt;
286	    }
287	
288	    if (opt.fec_l == 0 || opt.fec_d == 0) {
289	        std::cerr << "--fec-l and --fec-d must be greater than 0\n";
290	        return std::nullopt;
291	    }
292	
293	    if (opt.mcast_ttl < 0 || opt.mcast_ttl > 255) {
294	        std::cerr << "--mcast-ttl must be 0..255\n";
295	        return std::nullopt;
296	    }
297	
298	    return opt;
299	}
