301	struct udp_rtp_sender {
302	    int fd{-1};
303	    sockaddr_in addr{};
304	
305	    std::uint32_t ssrc{0};
306	    std::uint8_t pt{33};
307	    std::uint16_t seq{0};
308	    std::uint32_t timestamp{0};
309	
310	    std::size_t payload_size{1316};
311	    bool mpegts_payload{false};
312	
313	    std::string mcast_if{};
314	    int mcast_ttl{1};
315	    int mcast_loop{1};
316	
317	    bool open(const std::string& ip, std::uint16_t port) {
318	        fd = ::socket(AF_INET, SOCK_DGRAM, 0);
319	        if (fd < 0) {
320	            perror("socket");
321	            return false;
322	        }
323	
324	        std::memset(&addr, 0, sizeof(addr));
325	        addr.sin_family = AF_INET;
326	        addr.sin_port = htons(port);
327	
328	        if (::inet_pton(AF_INET, ip.c_str(), &addr.sin_addr) != 1) {
329	            std::cerr << "invalid ip: " << ip << "\n";
330	            return false;
331	        }
332	
333	        if (is_ipv4_multicast_addr(addr.sin_addr)) {
334	            if (!configure_multicast()) {
335	                return false;
336	            }
337	        }
338	
339	        return true;
340	    }
341	
342	    bool configure_multicast() {
343	        const unsigned char ttl = static_cast<unsigned char>(mcast_ttl);
344	        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
345	            perror("setsockopt IP_MULTICAST_TTL");
346	            return false;
347	        }
348	
349	        const unsigned char loop = static_cast<unsigned char>(mcast_loop != 0);
350	        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_LOOP, &loop, sizeof(loop)) < 0) {
351	            perror("setsockopt IP_MULTICAST_LOOP");
352	            return false;
353	        }
354	
355	        if (!mcast_if.empty()) {
356	            in_addr local_if{};
357	            if (::inet_pton(AF_INET, mcast_if.c_str(), &local_if) != 1) {
358	                std::cerr << "invalid --mcast-if: " << mcast_if << "\n";
359	                return false;
360	            }
361	
362	            if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_IF, &local_if, sizeof(local_if)) < 0) {
363	                perror("setsockopt IP_MULTICAST_IF");
364	                return false;
365	            }
366	        }
367	
368	        return true;
369	    }
370	
371	    void close() {
372	        if (fd >= 0) {
373	            ::close(fd);
374	            fd = -1;
375	        }
376	    }
377	
378	    void make_packet(std::vector<std::uint8_t>& out) {
379	        out.resize(12 + payload_size);
380	
381	        out[0] = 0x80;          // V=2, P=0, X=0, CC=0
382	        out[1] = pt & 0x7f;     // M=0, PT
383	
384	        put_u16_be(&out[2], seq);
385	        put_u32_be(&out[4], timestamp);
386	        put_u32_be(&out[8], ssrc);
387	
388	        auto* payload = out.data() + 12;
389	
390	        if (mpegts_payload) {
391	            // MPEG-TS風ダミーpayload。
392	            // 188 byteごとにsync byte 0x47を置くだけなので、再生可能なTSではない。
393	            for (std::size_t i = 0; i < payload_size; ++i) {
394	                payload[i] = (i % 188 == 0)
395	                    ? 0x47
396	                    : static_cast<std::uint8_t>((seq + i) & 0xff);
397	            }
398	        } else {
399	            for (std::size_t i = 0; i < payload_size; ++i) {
400	                payload[i] = static_cast<std::uint8_t>((seq + i) & 0xff);
401	            }
402	        }
403	    }
404	
405	    void send_packet(const std::vector<std::uint8_t>& packet) {
406	        const auto n = ::sendto(
407	            fd,
408	            packet.data(),
409	            packet.size(),
410	            0,
411	            reinterpret_cast<const sockaddr*>(&addr),
412	            sizeof(addr));
413	
414	        if (n < 0) {
415	            perror("sendto");
416	        }
417	    }
418	};
419	
420	struct fec_state {
421	    std::vector<std::uint8_t> row_xor;
422	    std::vector<std::uint8_t> col_xor;
423	
424	    std::uint32_t row_count{0};
425	    std::uint32_t col_count{0};
426	};
427	
428	void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
429	    constexpr std::size_t header_size = 12;
430	
431	    if (rtp_packet.size() < header_size) {
432	        return;
433	    }
434	
435	    const std::size_t payload_len = rtp_packet.size() - header_size;
436	
437	    if (acc.empty()) {
438	        acc.assign(payload_len, 0);
439	    }
440	
441	    const auto n = std::min(acc.size(), payload_len);
442	    for (std::size_t i = 0; i < n; ++i) {
443	        acc[i] ^= rtp_packet[header_size + i];
444	    }
445	}
446	
447	void make_fec_payload_packet(
448	    udp_rtp_sender& fec_sender,
449	    const std::vector<std::uint8_t>& xor_payload_data,
450	    std::vector<std::uint8_t>& out)
451	{
452	    fec_sender.payload_size = xor_payload_data.size();
453	    fec_sender.make_packet(out);
454	
455	    if (!xor_payload_data.empty()) {
456	        std::memcpy(out.data() + 12, xor_payload_data.data(), xor_payload_data.size());
457	    }
458	}
