478	
479	    const std::uint32_t ts_step =
480	        static_cast<std::uint32_t>(
481	            static_cast<double>(opt.clock_rate) / packets_per_sec);
482	
483	    udp_rtp_sender media;
484	    media.ssrc = opt.ssrc;
485	    media.pt = opt.pt;
486	    media.payload_size = opt.payload_size;
487	    media.mpegts_payload = opt.mpegts_payload;
488	    apply_mcast_options(media, opt);
489	
490	    if (!media.open(opt.dst, opt.port)) {
491	        return;
492	    }
493	
494	    udp_rtp_sender fec_row;
495	    udp_rtp_sender fec_col;
496	
497	    if (opt.fec) {
498	        fec_row.ssrc = opt.fec_row_ssrc;
499	        fec_row.pt = opt.fec_pt;
500	        fec_row.payload_size = opt.payload_size;
501	        fec_row.mpegts_payload = false;
502	        apply_mcast_options(fec_row, opt);
503	
504	        fec_col.ssrc = opt.fec_col_ssrc;
505	        fec_col.pt = opt.fec_pt;
506	        fec_col.payload_size = opt.payload_size;
507	        fec_col.mpegts_payload = false;
508	        apply_mcast_options(fec_col, opt);
509	
510	        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
511	            media.close();
512	            return;
513	        }
514	
515	        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
516	            media.close();
517	            fec_row.close();
518	            return;
519	        }
520	    }
521	
522	    std::cerr
523	        << "RTP media: " << opt.dst << ":" << opt.port
524	        << " ssrc=" << opt.ssrc
525	        << " pt=" << static_cast<int>(opt.pt)
526	        << " bitrate=" << opt.bitrate_bps
527	        << " payload=" << opt.payload_size
528	        << " pps=" << packets_per_sec
529	        << " ts_step=" << ts_step
530	        << "\n";
531	
532	    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
533	        std::cerr
534	            << "multicast: ttl=" << opt.mcast_ttl
535	            << " loop=" << opt.mcast_loop;
536	
537	        if (!opt.mcast_if.empty()) {
538	            std::cerr << " if=" << opt.mcast_if;
539	        } else {
540	            std::cerr << " if=<route-default>";
541	        }
542	
543	        std::cerr << "\n";
544	    }
545	
546	    if (opt.fec) {
547	        std::cerr
548	            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
549	            << " ssrc=" << opt.fec_row_ssrc
550	            << " pt=" << static_cast<int>(opt.fec_pt)
551	            << " L=" << opt.fec_l
552	            << "\n";
553	
554	        std::cerr
555	            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
556	            << " ssrc=" << opt.fec_col_ssrc
557	            << " pt=" << static_cast<int>(opt.fec_pt)
558	            << " D=" << opt.fec_d
559	            << "\n";
560	    }
561	
562	    std::mt19937 rng{std::random_device{}()};
563	    std::uniform_real_distribution<double> dist{0.0, 1.0};
564	
565	    std::vector<std::uint8_t> media_packet;
566	    std::vector<std::uint8_t> delayed_packet;
567	    bool has_delayed_packet = false;
568	
569	    fec_state fec;
570	    std::vector<std::uint8_t> fec_packet;
571	
572	    auto next = clock_type::now();
573	
574	    while (!g_stop) {
575	        if (has_delayed_packet) {
576	            media.send_packet(delayed_packet);
577	            has_delayed_packet = false;
578	        }
579	
580	        media.make_packet(media_packet);
581	
582	        if (opt.fec) {
583	            xor_payload(fec.row_xor, media_packet);
584	            xor_payload(fec.col_xor, media_packet);
585	
586	            ++fec.row_count;
587	            ++fec.col_count;
588	
589	            if (fec.row_count >= opt.fec_l) {
590	                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
591	                fec_row.send_packet(fec_packet);
592	
593	                ++fec_row.seq;
594	                fec_row.timestamp += ts_step * opt.fec_l;
595	
596	                fec.row_xor.clear();
597	                fec.row_count = 0;
598	            }
599	
600	            if (fec.col_count >= opt.fec_d) {
601	                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
602	                fec_col.send_packet(fec_packet);
603	
604	                ++fec_col.seq;
605	                fec_col.timestamp += ts_step * opt.fec_d;
606	
607	                fec.col_xor.clear();
608	                fec.col_count = 0;
609	            }
610	        }
611	
612	        const bool drop = dist(rng) < opt.loss_rate;
613	        const bool duplicate = dist(rng) < opt.duplicate_rate;
614	        const bool reorder = dist(rng) < opt.reorder_rate;
615	
616	        if (!drop) {
617	            if (reorder && !has_delayed_packet) {
618	                delayed_packet = media_packet;
619	                has_delayed_packet = true;
620	            } else {
621	                media.send_packet(media_packet);
622	            }
623	
624	            if (duplicate) {
625	                media.send_packet(media_packet);
626	            }
627	        }
628	
629	        ++media.seq;
630	        media.timestamp += ts_step;
631	
632	        next += interval;
633	        std::this_thread::sleep_until(next);
634	    }
635	
636	    media.close();
637	
638	    if (opt.fec) {
639	        fec_row.close();
640	        fec_col.close();
641	    }
642	}
