691	        << " bitrate=" << opt.bitrate_bps
692	        << " payload=" << opt.payload_size
693	        << " pps=" << packets_per_sec
694	        << "\n";
695	
696	    auto next = clock_type::now();
697	    std::uint64_t counter = 0;
698	
699	    while (!g_stop) {
700	        for (std::size_t i = 0; i < payload.size(); ++i) {
701	            payload[i] = static_cast<char>((counter + i) & 0xff);
702	        }
703	
704	        const int ret = srt_sendmsg(
705	            sock,
706	            payload.data(),
707	            static_cast<int>(payload.size()),
708	            -1,
709	            0);
710	
711	        if (ret == SRT_ERROR) {
712	            std::cerr << "srt_sendmsg failed: " << srt_getlasterror_str() << "\n";
713	            break;
714	        }
715	
716	        ++counter;
717	
718	        next += interval;
719	        std::this_thread::sleep_until(next);
720	    }
721	
722	    srt_close(sock);
723	#endif
