#include "stream_srt.h"

#include <cstdio>
#include <iostream>
#include <utility>

#include "json.h"
#include "trace.h"
#include "stream_json.h"
#include "tsv_util.h"

namespace srt {

flow::flow(const stream_id& sid, const flow_id fid, std::string interface_name, event_sink &events)
	: m_fid(std::move(fid))
	, m_interface_name(std::move(interface_name))
	, m_events(events) {
	m_identity = flow_identity_cache{
		.stream_key = make_stream_key(sid),
		.flow_key = make_flow_key(sid, m_fid),
	};
	m_text.src = to_string(m_fid.src);
	m_text.dst = to_string(m_fid.dst);
	m_event.source = stream_json::make_flow_event_source("SRT",
	                                                        m_fid.interface_id,
	                                                        m_interface_name,
	                                                        m_identity.stream_key,
	                                                        m_identity.flow_key,
	                                                        m_fid.vlan);
}

void flow::update_role(const info &i) {
	const flow_role observed = (i.iscontrol != 0) ? flow_role::control : flow_role::data;

	if(m_role == flow_role::unknown) {
		m_role = observed;
	}
	else if(m_role != observed && m_role != flow_role::mixed) {
		m_role = flow_role::mixed;
	}

	m_text.role = to_string(m_role);
}

int flow::process(const info &i) {
	touch(i.time_epoch);
	update_role(i);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.interval.update(i.time_epoch);
	m_metrics.packet_rate.update(i.time_epoch);
	m_metrics.packet_count.inc();
	m_metrics.packet_counts.update(i.iscontrol != 0, i.msg_rexmit != 0);

	if(i.iscontrol != 0) {
		m_metrics.control_types.update(i.type);
		if(i.type == 0x0003) {
			m_metrics.nak_seq_stats.add(static_cast<double>(i.nak_seqno));
		}
	}
	else {
		auto seq_update = m_metrics.seq_stats.update(i.seqno);
		m_event.packet.loss_gap_count += seq_update.gap_added;
		if(seq_update.duplicate) {
			++m_event.packet.duplicate_count;
		}
		if(seq_update.reordered) {
			++m_event.packet.reorder_count;
		}
	}

	if(i.has_rtt)     m_metrics.rtt.update(static_cast<double>(i.rtt));
	if(i.has_rttvar)  m_metrics.rttvar.update(static_cast<double>(i.rttvar));
	if(i.has_rate)    m_metrics.rate.update(static_cast<double>(i.rate));
	if(i.has_rcvrate) m_metrics.rcvrate.update(static_cast<double>(i.rcvrate));
	if(i.has_bw)      m_metrics.bw.update(static_cast<double>(i.bw));

	return 0;
}

void flow::emit_detected(double now) {
	m_events.emit(make_event(now, "flow_detected", json{
		{"interface_id", m_fid.interface_id},
		{"role", m_text.role},
		{"endpoint", {
			{"src", m_text.src},
			{"dst", m_text.dst},
		}},
		{"vlan", m_fid.vlan.empty() ? json(nullptr) : tsv::to_json(m_fid.vlan)},
	}));
}

void flow::emit_lost(double now) {
	m_events.emit(make_event(now, "flow_lost", json{
		{"interface_id", m_fid.interface_id},
		{"role", m_text.role},
		{"endpoint", {
			{"src", m_text.src},
			{"dst", m_text.dst},
		}},
		{"last_seen", last_seen()},
	}));
}

json flow::to_list_json(double now) const {
	(void)now;
	json j = stream_json::make_flow_list_base(m_identity.flow_key,
	                                               m_fid.interface_id,
	                                               m_interface_name,
	                                               m_fid.vlan);
	j["role"] = m_text.role;
	j["endpoint"] = {
		{"src", m_text.src},
		{"dst", m_text.dst},
	};
	j["last_seen"] = last_seen();
	return j;
}

