	        std::uint64_t seq_cycles = cycles_;

	        if (seq < max_seq_) {
	            if ((max_seq_ - seq) > 0x8000) {
	                cycles_ += 0x10000ULL;
	                seq_cycles = cycles_;
	                max_seq_ = seq;
