575	class packet_scheduler {
576	public:
577	    packet_scheduler(const options& opt, packet_submitter send)
578	        : jitter_ms_(opt.jitter_ms)
579	        , send_(std::move(send))
580	        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
581	        , jitter_distribution_(0.0, jitter_ms_) {}
582	
583	    void submit(packet value) {
584	        auto due = clock_type::now();
585	        if (jitter_ms_ > 0.0) {
586	            due += std::chrono::duration_cast<clock_type::duration>(
587	                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
588	        }
589	
590	        if (last_due_ && due < *last_due_) {
591	            due = *last_due_;
592	        }
593	
594	        std::this_thread::sleep_until(due);
595	        send_(std::move(value));
596	        last_due_ = due;
597	    }
598	
599	private:
600	    double jitter_ms_{0.0};
601	    packet_submitter send_;
602	    std::mt19937 rng_;
603	    std::uniform_real_distribution<double> jitter_distribution_;
604	    std::optional<clock_type::time_point> last_due_;
605	};
