perl -0pi -e 's@#include <map>
#include <optional>@#include <map>
#include <memory>
#include <optional>@' be/tools/streamgen.cc
perl -0pi -e 's@
void run_srt\(const options& opt\) \{@
#ifdef ENABLE_SRT
class srt_impairment_proxy {
public:
    explicit srt_impairment_proxy(const options& opt)
        : jitter_ms_(opt.jitter_ms)
        , rng_(opt.seed ? (*opt.seed ^ 0x85ebca6bU) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , impairment_(opt, [this](packet value) {
            schedule(std::move(value));
        }) {}

    ~srt_impairment_proxy() {
        stop();
    }

    bool open(const std::string& dst, std::uint16_t port) {
        downstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (downstream_fd_ < 0) {
            perror("SRT proxy downstream socket");
            return false;
        }

        std::memset(&destination_, 0, sizeof(destination_));
        destination_.sin_family = AF_INET;
        destination_.sin_port = htons(port);
        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
            std::cerr << "invalid SRT destination ip: " << dst << "\n";
            close_fds();
            return false;
        }

        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (upstream_fd_ < 0) {
            perror("SRT proxy upstream socket");
            close_fds();
            return false;
        }

        sockaddr_in listen{};
        listen.sin_family = AF_INET;
        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        listen.sin_port = 0;
        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
            perror("SRT proxy bind");
            close_fds();
            return false;
        }

        socklen_t length = sizeof(listen);
        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
            perror("SRT proxy getsockname");
            close_fds();
            return false;
        }

        local_port_ = ntohs(listen.sin_port);
        return true;
    }

    void start() {
        worker_ = std::thread([this] { run(); });
    }

    void stop() {
        stopping_ = true;
        if (worker_.joinable()) {
            worker_.join();
        }
        close_fds();
    }

    std::uint16_t local_port() const {
        return local_port_;
    }

private:
    static bool is_data_packet(const packet& value) {
        return value.size() >= 16 && (value[0] & 0x80U) == 0;
    }

    void close_fds() {
        if (upstream_fd_ >= 0) {
            ::close(upstream_fd_);
            upstream_fd_ = -1;
        }
        if (downstream_fd_ >= 0) {
            ::close(downstream_fd_);
            downstream_fd_ = -1;
        }
    }

    void send_downstream(const packet& value) {
        const auto sent = ::sendto(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&destination_),
            sizeof(destination_));
        if (sent < 0) {
            perror("SRT proxy send downstream");
        }
    }

    void send_upstream(const packet& value) {
        if (!has_sender_) {
            return;
        }

        const auto sent = ::sendto(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&sender_),
            sender_length_);
        if (sent < 0) {
            perror("SRT proxy send upstream");
        }
    }

    void schedule(packet value) {
        auto due = clock_type::now();
        if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (last_due_ && due < *last_due_) {
            due = *last_due_;
        }

        scheduled_.emplace(due, std::move(value));
        last_due_ = due;
    }

    void flush_ready() {
        const auto now = clock_type::now();
        while (!scheduled_.empty() && scheduled_.begin()->first <= now) {
            send_downstream(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
        }
    }

    void forward_from_upstream() {
        packet value(65536);
        sockaddr_storage source{};
        socklen_t source_length = sizeof(source);
        const auto received = ::recvfrom(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<sockaddr*>(&source),
            &source_length);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        sender_ = source;
        sender_length_ = source_length;
        has_sender_ = true;

        if (is_data_packet(value)) {
            impairment_.submit(std::move(value));
        } else {
            send_downstream(value);
        }
    }

    void forward_from_downstream() {
        packet value(65536);
        const auto received = ::recvfrom(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            nullptr,
            nullptr);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        send_upstream(value);
    }

    void run() {
        while (!stopping_) {
            pollfd fds[2]{};
            fds[0].fd = upstream_fd_;
            fds[0].events = POLLIN;
            fds[1].fd = downstream_fd_;
            fds[1].events = POLLIN;

            const int result = ::poll(fds, 2, 10);
            if (result > 0) {
                if ((fds[0].revents & POLLIN) != 0) {
                    forward_from_upstream();
                }
                if ((fds[1].revents & POLLIN) != 0) {
                    forward_from_downstream();
                }
            }

            flush_ready();
        }
    }

    int upstream_fd_{-1};
    int downstream_fd_{-1};
    sockaddr_in destination_{};
    sockaddr_storage sender_{};
    socklen_t sender_length_{0};
    bool has_sender_{false};
    std::uint16_t local_port_{0};
    double jitter_ms_{0.0};
    std::mt19937 rng_;
    std::uniform_real_distribution<double> jitter_distribution_;
    std::optional<clock_type::time_point> last_due_;
    std::multimap<clock_type::time_point, packet> scheduled_;
    packet_impairer impairment_;
    std::atomic<bool> stopping_{false};
    std::thread worker_;
};
#endif

