 102	std::uint16_t parse_u16(const char* s, const char* name) {
 103	    const auto v = std::stoul(s);
 104	    if (v > 65535) {
 105	        throw std::runtime_error(std::string(name) + " out of range: " + s);
 106	    }
 107	    return static_cast<std::uint16_t>(v);
 108	}
