 816	
 817	    bool open(const std::string& dst, std::uint16_t port) {
 818	        downstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
 819	        if (downstream_fd_ < 0) {
 820	            perror("SRT proxy downstream socket");
 821	            return false;
 822	        }
 823	
 824	        std::memset(&destination_, 0, sizeof(destination_));
 825	        destination_.sin_family = AF_INET;
 826	        destination_.sin_port = htons(port);
 827	        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
 828	            std::cerr << "invalid SRT destination ip: " << dst << "\n";
 829	            close_fds();
 830	            return false;
 831	        }
 832	
 833	        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
 834	        if (upstream_fd_ < 0) {
 835	            perror("SRT proxy upstream socket");
 836	            close_fds();
 837	            return false;
 838	        }
 839	
 840	        sockaddr_in listen{};
 841	        listen.sin_family = AF_INET;
 842	        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
 843	        listen.sin_port = 0;
 844	        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
 845	            perror("SRT proxy bind");
 846	            close_fds();
 847	            return false;
 848	        }
 849	
 850	        socklen_t length = sizeof(listen);
 851	        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
 852	            perror("SRT proxy getsockname");
 853	            close_fds();
 854	            return false;
 855	        }
 856	
 857	        local_port_ = ntohs(listen.sin_port);
 858	        return true;
 859	    }
 860	
 861	    void start() {
 862	        worker_ = std::thread([this] { run(); });
 863	    }
 864	
 865	    void stop() {
 866	        stopping_ = true;
 867	        if (worker_.joinable()) {
 868	            worker_.join();
 869	        }
 870	        close_fds();
 871	    }
 872	
 873	    std::uint16_t local_port() const {
 874	        return local_port_;
 875	    }
