 510	using packet = std::vector<std::uint8_t>;
 511	using packet_submitter = std::function<void(packet)>;
 512	
 513	class packet_impairer {
 514	public:
 515	    packet_impairer(const options& opt, packet_submitter submit)
 516	        : loss_rate_(opt.loss_rate)
 517	        , duplicate_rate_(opt.duplicate_rate)
 518	        , reorder_rate_(opt.reorder_rate)
 519	        , submit_(std::move(submit))
 520	        , rng_(opt.seed ? *opt.seed : std::random_device{}()) {}
 521	
 522	    void submit(packet value) {
 523	        const bool drop = hit(loss_rate_);
 524	        const bool duplicate = hit(duplicate_rate_);
 525	        const bool reorder = hit(reorder_rate_);
 526	
 527	        if (delayed_) {
 528	            if (!drop) {
 529	                submit_with_duplicate(std::move(value), duplicate);
 530	            }
 531	            submit_(std::move(*delayed_));
 532	            delayed_.reset();
 533	            return;
 534	        }
 535	
 536	        if (drop) {
 537	            return;
 538	        }
 539	
 540	        if (reorder) {
 541	            delayed_ = std::move(value);
 542	            return;
 543	        }
 544	
 545	        submit_with_duplicate(std::move(value), duplicate);
 546	    }
 547	
 548	    void flush() {
 549	        if (delayed_) {
 550	            submit_(std::move(*delayed_));
 551	            delayed_.reset();
 552	        }
 553	    }
 554	
 555	private:
 556	    bool hit(double rate) {
 557	        return rate > 0.0 && distribution_(rng_) < rate;
 558	    }
 559	
 560	    void submit_with_duplicate(packet value, bool duplicate) {
 561	        if (duplicate) {
 562	            submit_(value);
 563	        }
 564	        submit_(std::move(value));
 565	    }
 566	
 567	    double loss_rate_{0.0};
 568	    double duplicate_rate_{0.0};
 569	    double reorder_rate_{0.0};
 570	    packet_submitter submit_;
 571	    std::mt19937 rng_;
 572	    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
 573	    std::optional<packet> delayed_;
 574	};
 575	
 576	class packet_scheduler {
 577	public:
 578	    packet_scheduler(const options& opt, packet_submitter send)
 579	        : jitter_ms_(opt.jitter_ms)
 580	        , send_(std::move(send))
 581	        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
 582	        , jitter_distribution_(0.0, jitter_ms_) {}
 583	
 584	    void set_base_time(clock_type::time_point value) {
 585	        base_time_ = value;
 586	    }
 587	
 588	    void submit(packet value) {
 589	        auto due = base_time_.value_or(clock_type::now());
 590	        if (jitter_ms_ > 0.0) {
 591	            due += std::chrono::duration_cast<clock_type::duration>(
 592	                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
 593	        }
 594	
 595	        if (last_due_ && due < *last_due_) {
 596	            due = *last_due_;
 597	        }
 598	
 599	        std::this_thread::sleep_until(due);
 600	        send_(std::move(value));
 601	        last_due_ = due;
 602	    }
 603	
 604	private:
 605	    double jitter_ms_{0.0};
 606	    packet_submitter send_;
 607	    std::mt19937 rng_;
 608	    std::uniform_real_distribution<double> jitter_distribution_;
 609	    std::optional<clock_type::time_point> base_time_;
 610	    std::optional<clock_type::time_point> last_due_;
 611	};
