 803	class srt_impairment_proxy {
 804	public:
 805	    explicit srt_impairment_proxy(const options& opt)
 806	        : jitter_ms_(opt.jitter_ms)
 807	        , rng_(opt.seed ? (*opt.seed ^ 0x85ebca6bU) : std::random_device{}())
 808	        , jitter_distribution_(0.0, jitter_ms_)
 809	        , impairment_(opt, [this](packet value) {
 810	            schedule(std::move(value));
 811	        }) {}
 812	
 813	    ~srt_impairment_proxy() {
 814	        stop();
 815	    }
 816	
 817	    bool open(const std::string& dst, std::uint16_t port) {
 818	        downstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
 819	        if (downstream_fd_ < 0) {
 820	            perror("SRT proxy downstream socket");
 821	            return false;
 822	        }
 823	
 824	        std::memset(&destination_, 0, sizeof(destination_));
 825	        destination_.sin_family = AF_INET;
 826	        destination_.sin_port = htons(port);
 827	        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
 828	            std::cerr << "invalid SRT destination ip: " << dst << "\n";
 829	            close_fds();
 830	            return false;
 831	        }
 832	
 833	        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
 834	        if (upstream_fd_ < 0) {
 835	            perror("SRT proxy upstream socket");
 836	            close_fds();
 837	            return false;
 838	        }
 839	
 840	        sockaddr_in listen{};
 841	        listen.sin_family = AF_INET;
 842	        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
 843	        listen.sin_port = 0;
 844	        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
 845	            perror("SRT proxy bind");
 846	            close_fds();
 847	            return false;
 848	        }
 849	
 850	        socklen_t length = sizeof(listen);
 851	        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
 852	            perror("SRT proxy getsockname");
 853	            close_fds();
 854	            return false;
 855	        }
 856	
 857	        local_port_ = ntohs(listen.sin_port);
 858	        return true;
 859	    }
 860	
 861	    void start() {
 862	        worker_ = std::thread([this] { run(); });
 863	    }
 864	
 865	    void stop() {
 866	        stopping_ = true;
 867	        if (worker_.joinable()) {
 868	            worker_.join();
 869	        }
 870	        close_fds();
 871	    }
 872	
 873	    std::uint16_t local_port() const {
 874	        return local_port_;
 875	    }
 876	
 877	private:
 878	    static bool is_data_packet(const packet& value) {
 879	        return value.size() >= 16 && (value[0] & 0x80U) == 0;
 880	    }
 881	
 882	    void close_fds() {
 883	        if (upstream_fd_ >= 0) {
 884	            ::close(upstream_fd_);
 885	            upstream_fd_ = -1;
 886	        }
 887	        if (downstream_fd_ >= 0) {
 888	            ::close(downstream_fd_);
 889	            downstream_fd_ = -1;
 890	        }
 891	    }
 892	
 893	    void send_downstream(const packet& value) {
 894	        const auto sent = ::sendto(
 895	            downstream_fd_,
 896	            value.data(),
 897	            value.size(),
 898	            0,
 899	            reinterpret_cast<const sockaddr*>(&destination_),
 900	            sizeof(destination_));
 901	        if (sent < 0) {
 902	            perror("SRT proxy send downstream");
 903	        }
 904	    }
 905	
 906	    void send_upstream(const packet& value) {
 907	        if (!has_sender_) {
 908	            return;
 909	        }
 910	
 911	        const auto sent = ::sendto(
 912	            upstream_fd_,
 913	            value.data(),
 914	            value.size(),
 915	            0,
 916	            reinterpret_cast<const sockaddr*>(&sender_),
 917	            sender_length_);
 918	        if (sent < 0) {
 919	            perror("SRT proxy send upstream");
 920	        }
 921	    }
 922	
 923	    void schedule(packet value) {
 924	        auto due = clock_type::now();
 925	        if (jitter_ms_ > 0.0) {
 926	            due += std::chrono::duration_cast<clock_type::duration>(
 927	                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
 928	        }
 929	
 930	        if (last_due_ && due < *last_due_) {
 931	            due = *last_due_;
 932	        }
 933	
 934	        scheduled_.emplace(due, std::move(value));
 935	        last_due_ = due;
 936	    }
 937	
 938	    void flush_ready() {
 939	        const auto now = clock_type::now();
 940	        while (!scheduled_.empty() && scheduled_.begin()->first <= now) {
 941	            send_downstream(scheduled_.begin()->second);
 942	            scheduled_.erase(scheduled_.begin());
 943	        }
 944	    }
 945	
 946	    void forward_from_upstream() {
 947	        packet value(65536);
 948	        sockaddr_storage source{};
 949	        socklen_t source_length = sizeof(source);
 950	        const auto received = ::recvfrom(
 951	            upstream_fd_,
 952	            value.data(),
 953	            value.size(),
 954	            0,
 955	            reinterpret_cast<sockaddr*>(&source),
 956	            &source_length);
 957	        if (received <= 0) {
 958	            return;
 959	        }
 960	
 961	        value.resize(static_cast<std::size_t>(received));
 962	        sender_ = source;
 963	        sender_length_ = source_length;
 964	        has_sender_ = true;
 965	
 966	        if (is_data_packet(value)) {
 967	            impairment_.submit(std::move(value));
 968	        } else {
 969	            send_downstream(value);
 970	        }
 971	    }
 972	
 973	    void forward_from_downstream() {
 974	        packet value(65536);
 975	        const auto received = ::recvfrom(
 976	            downstream_fd_,
 977	            value.data(),
 978	            value.size(),
 979	            0,
 980	            nullptr,
 981	            nullptr);
 982	        if (received <= 0) {
 983	            return;
 984	        }
 985	
 986	        value.resize(static_cast<std::size_t>(received));
 987	        send_upstream(value);
 988	    }
 989	
 990	    void run() {
 991	        while (!stopping_) {
 992	            pollfd fds[2]{};
 993	            fds[0].fd = upstream_fd_;
 994	            fds[0].events = POLLIN;
 995	            fds[1].fd = downstream_fd_;
 996	            fds[1].events = POLLIN;
 997	
 998	            const int result = ::poll(fds, 2, 10);
 999	            if (result > 0) {
1000	                if ((fds[0].revents & POLLIN) != 0) {
1001	                    forward_from_upstream();
1002	                }
1003	                if ((fds[1].revents & POLLIN) != 0) {
1004	                    forward_from_downstream();
1005	                }
1006	            }
1007	
1008	            flush_ready();
1009	        }
1010	    }
1011	
1012	    int upstream_fd_{-1};
1013	    int downstream_fd_{-1};
1014	    sockaddr_in destination_{};
1015	    sockaddr_storage sender_{};
1016	    socklen_t sender_length_{0};
1017	    bool has_sender_{false};
1018	    std::uint16_t local_port_{0};
1019	    double jitter_ms_{0.0};
1020	    std::mt19937 rng_;
1021	    std::uniform_real_distribution<double> jitter_distribution_;
1022	    std::optional<clock_type::time_point> last_due_;
1023	    std::multimap<clock_type::time_point, packet> scheduled_;
1024	    packet_impairer impairment_;
1025	    std::atomic<bool> stopping_{false};
1026	    std::thread worker_;
1027	};
