1030	void run_srt(const options& opt) {
1031	#ifndef ENABLE_SRT
1032	    std::cerr << "SRT disabled. Build with -DENABLE_SRT and link libsrt.\n";
1033	    (void)opt;
1034	#else
1035	    SRTSOCKET sock = srt_create_socket();
1036	    if (sock == SRT_INVALID_SOCK) {
1037	        std::cerr << "srt_create_socket failed\n";
1038	        return;
1039	    }
1040	
1041	    std::unique_ptr<srt_impairment_proxy> proxy;
1042	    std::string connect_dst = opt.dst;
1043	    std::uint16_t connect_port = opt.port;
1044	    if (impairment_enabled(opt)) {
1045	        proxy = std::make_unique<srt_impairment_proxy>(opt);
1046	        if (!proxy->open(opt.dst, opt.port)) {
1047	            srt_close(sock);
1048	            return;
1049	        }
1050	        proxy->start();
1051	        connect_dst = "127.0.0.1";
1052	        connect_port = proxy->local_port();
1053	    }
1054	
1055	    int yes = 1;
1056	    srt_setsockopt(sock, 0, SRTO_SENDER, &yes, sizeof(yes));
1057	
1058	    sockaddr_in sa{};
1059	    sa.sin_family = AF_INET;
1060	    sa.sin_port = htons(connect_port);
1061	
1062	    if (::inet_pton(AF_INET, connect_dst.c_str(), &sa.sin_addr) != 1) {
1063	        std::cerr << "invalid ip: " << connect_dst << "\n";
1064	        srt_close(sock);
1065	        if (proxy) proxy->stop();
1066	        return;
1067	    }
1068	
1069	    if (srt_connect(sock, reinterpret_cast<sockaddr*>(&sa), sizeof(sa)) == SRT_ERROR) {
1070	        std::cerr << "srt_connect failed: " << srt_getlasterror_str() << "\n";
1071	        srt_close(sock);
1072	        if (proxy) proxy->stop();
1073	        return;
1074	    }
1075	
1076	    const double packets_per_sec =
1077	        static_cast<double>(opt.bitrate_bps) /
1078	        static_cast<double>(opt.payload_size * 8);
1079	
1080	    if (packets_per_sec <= 0.0) {
1081	        std::cerr << "invalid SRT packets_per_sec\n";
1082	        srt_close(sock);
1083	        if (proxy) proxy->stop();
1084	        return;
1085	    }
1086	
1087	    const auto interval = std::chrono::nanoseconds(
1088	        static_cast<long long>(1'000'000'000.0 / packets_per_sec));
1089	
1090	    std::vector<char> payload(opt.payload_size, 0);
1091	
1092	    std::cerr
1093	        << "SRT: " << opt.dst << ":" << opt.port
1094	        << " bitrate=" << opt.bitrate_bps
1095	        << " payload=" << opt.payload_size
1096	        << " pps=" << packets_per_sec
1097	        << "\n";
1098	
1099	    if (proxy) {
1100	        std::cerr << "SRT impairment proxy: 127.0.0.1:" << proxy->local_port()
1101	                  << " -> " << opt.dst << ":" << opt.port << "\n";
1102	    }
1103	    print_impairment(opt);
1104	
1105	    auto next = clock_type::now();
1106	    std::uint64_t counter = 0;
1107	
1108	    while (!g_stop) {
1109	        for (std::size_t i = 0; i < payload.size(); ++i) {
1110	            payload[i] = static_cast<char>((counter + i) & 0xff);
1111	        }
1112	
1113	        const int ret = srt_sendmsg(
1114	            sock,
1115	            payload.data(),
1116	            static_cast<int>(payload.size()),
1117	            -1,
1118	            0);
1119	
1120	        if (ret == SRT_ERROR) {
1121	            std::cerr << "srt_sendmsg failed: " << srt_getlasterror_str() << "\n";
1122	            break;
1123	        }
1124	
1125	        ++counter;
1126	
1127	        next += interval;
1128	        std::this_thread::sleep_until(next);
1129	    }
1130	
1131	    srt_close(sock);
1132	    if (proxy) proxy->stop();
1133	#endif
1134	}
