 173	std::optional<options> parse_args(int argc, char** argv) {
 174	    options opt;
 175	
 176	    try {
 177	        for (int i = 1; i < argc; ++i) {
 178	            std::string a = argv[i];
 179	
 180	            auto next = [&](const char* name) -> const char* {
 181	                if (!need_value(i, argc, name)) {
 182	                    return nullptr;
 183	                }
 184	                return argv[++i];
 185	            };
 186	
 187	            if (a == "--proto") {
 188	                const char* v = next("--proto");
 189	                if (!v) return std::nullopt;
 190	
 191	                std::string s = v;
 192	                if (s == "rtp") {
 193	                    opt.proto = proto_type::rtp;
 194	                } else if (s == "srt") {
 195	                    opt.proto = proto_type::srt;
 196	                } else {
 197	                    std::cerr << "invalid proto: " << s << "\n";
 198	                    return std::nullopt;
 199	                }
 200	            } else if (a == "--dst") {
 201	                const char* v = next("--dst");
 202	                if (!v) return std::nullopt;
 203	                opt.dst = v;
 204	            } else if (a == "--port") {
 205	                const char* v = next("--port");
 206	                if (!v) return std::nullopt;
 207	                opt.port = parse_u16(v, "--port");
 208	            } else if (a == "--bitrate") {
 209	                const char* v = next("--bitrate");
 210	                if (!v) return std::nullopt;
 211	                opt.bitrate_bps = static_cast<std::uint32_t>(std::stoul(v));
 212	            } else if (a == "--payload-size") {
 213	                const char* v = next("--payload-size");
 214	                if (!v) return std::nullopt;
 215	                opt.payload_size = static_cast<std::size_t>(std::stoull(v));
 216	            } else if (a == "--ssrc") {
 217	                const char* v = next("--ssrc");
 218	                if (!v) return std::nullopt;
 219	                opt.ssrc = static_cast<std::uint32_t>(std::stoul(v));
 220	            } else if (a == "--pt") {
 221	                const char* v = next("--pt");
 222	                if (!v) return std::nullopt;
 223	                opt.pt = parse_u8(v, "--pt");
 224	            } else if (a == "--clock-rate") {
 225	                const char* v = next("--clock-rate");
 226	                if (!v) return std::nullopt;
 227	                opt.clock_rate = static_cast<std::uint32_t>(std::stoul(v));
 228	            } else if (a == "--mpegts-payload") {
 229	                const char* v = next("--mpegts-payload");
 230	                if (!v) return std::nullopt;
 231	                opt.mpegts_payload = std::stoul(v) != 0;
 232	            } else if (a == "--loss") {
 233	                const char* v = next("--loss");
 234	                if (!v) return std::nullopt;
 235	                opt.loss_rate = std::stod(v);
 236	            } else if (a == "--duplicate") {
 237	                const char* v = next("--duplicate");
 238	                if (!v) return std::nullopt;
 239	                opt.duplicate_rate = std::stod(v);
 240	            } else if (a == "--reorder") {
 241	                const char* v = next("--reorder");
 242	                if (!v) return std::nullopt;
 243	                opt.reorder_rate = std::stod(v);
 244	            } else if (a == "--jitter-ms") {
 245	                const char* v = next("--jitter-ms");
 246	                if (!v) return std::nullopt;
 247	                opt.jitter_ms = std::stod(v);
 248	            } else if (a == "--seed") {
 249	                const char* v = next("--seed");
 250	                if (!v) return std::nullopt;
 251	                opt.seed = parse_u32(v, "--seed");
 252	            } else if (a == "--fec") {
 253	                opt.fec = true;
 254	            } else if (a == "--fec-row-port") {
 255	                const char* v = next("--fec-row-port");
 256	                if (!v) return std::nullopt;
 257	                opt.fec_row_port = parse_u16(v, "--fec-row-port");
 258	            } else if (a == "--fec-col-port") {
 259	                const char* v = next("--fec-col-port");
 260	                if (!v) return std::nullopt;
 261	                opt.fec_col_port = parse_u16(v, "--fec-col-port");
 262	            } else if (a == "--fec-pt") {
 263	                const char* v = next("--fec-pt");
 264	                if (!v) return std::nullopt;
 265	                opt.fec_pt = parse_u8(v, "--fec-pt");
 266	            } else if (a == "--fec-row-ssrc") {
 267	                const char* v = next("--fec-row-ssrc");
 268	                if (!v) return std::nullopt;
 269	                opt.fec_row_ssrc = static_cast<std::uint32_t>(std::stoul(v));
 270	            } else if (a == "--fec-col-ssrc") {
 271	                const char* v = next("--fec-col-ssrc");
 272	                if (!v) return std::nullopt;
 273	                opt.fec_col_ssrc = static_cast<std::uint32_t>(std::stoul(v));
 274	            } else if (a == "--fec-l") {
 275	                const char* v = next("--fec-l");
 276	                if (!v) return std::nullopt;
 277	                opt.fec_l = static_cast<std::uint32_t>(std::stoul(v));
 278	            } else if (a == "--fec-d") {
 279	                const char* v = next("--fec-d");
 280	                if (!v) return std::nullopt;
 281	                opt.fec_d = static_cast<std::uint32_t>(std::stoul(v));
 282	            } else if (a == "--mcast-if") {
 283	                const char* v = next("--mcast-if");
 284	                if (!v) return std::nullopt;
 285	                opt.mcast_if = v;
 286	            } else if (a == "--mcast-ttl") {
 287	                const char* v = next("--mcast-ttl");
 288	                if (!v) return std::nullopt;
 289	                opt.mcast_ttl = std::stoi(v);
 290	            } else if (a == "--mcast-loop") {
 291	                const char* v = next("--mcast-loop");
 292	                if (!v) return std::nullopt;
 293	                opt.mcast_loop = std::stoi(v);
 294	            } else if (a == "--help" || a == "-h") {
 295	                return std::nullopt;
 296	            } else {
 297	                std::cerr << "unknown option: " << a << "\n";
 298	                return std::nullopt;
 299	            }
 300	        }
 301	    } catch (const std::exception& e) {
 302	        std::cerr << "argument parse error: " << e.what() << "\n";
 303	        return std::nullopt;
 304	    }
 305	
 306	    if (opt.payload_size == 0) {
 307	        std::cerr << "--payload-size must be greater than 0\n";
 308	        return std::nullopt;
 309	    }
 310	
 311	    if (opt.bitrate_bps == 0) {
 312	        std::cerr << "--bitrate must be greater than 0\n";
 313	        return std::nullopt;
 314	    }
 315	
 316	    const auto valid_rate = [](double value) {
 317	        return std::isfinite(value) && value >= 0.0 && value <= 1.0;
 318	    };
 319	
 320	    if (!valid_rate(opt.loss_rate) ||
 321	        !valid_rate(opt.duplicate_rate) ||
 322	        !valid_rate(opt.reorder_rate)) {
 323	        std::cerr << "--loss, --duplicate, and --reorder must be rates in 0..1\n";
 324	        return std::nullopt;
 325	    }
 326	
 327	    if (!std::isfinite(opt.jitter_ms) || opt.jitter_ms < 0.0 || opt.jitter_ms > 60000.0) {
 328	        std::cerr << "--jitter-ms must be in 0..60000\n";
 329	        return std::nullopt;
 330	    }
 331	
 332	    if (opt.fec_l == 0 || opt.fec_d == 0) {
 333	        std::cerr << "--fec-l and --fec-d must be greater than 0\n";
 334	        return std::nullopt;
 335	    }
 336	
 337	    if (opt.mcast_ttl < 0 || opt.mcast_ttl > 255) {
 338	        std::cerr << "--mcast-ttl must be 0..255\n";
 339	        return std::nullopt;
 340	    }
 341	
 342	    return opt;
 343	}
