 638	void run_rtp(const options& opt) {
 639	    const double packets_per_sec =
 640	        static_cast<double>(opt.bitrate_bps) /
 641	        static_cast<double>(opt.payload_size * 8);
 642	
 643	    if (packets_per_sec <= 0.0) {
 644	        std::cerr << "invalid packets_per_sec\n";
 645	        return;
 646	    }
 647	
 648	    const auto interval = std::chrono::nanoseconds(
 649	        static_cast<long long>(1'000'000'000.0 / packets_per_sec));
 650	
 651	    const std::uint32_t ts_step =
 652	        static_cast<std::uint32_t>(
 653	            static_cast<double>(opt.clock_rate) / packets_per_sec);
 654	
 655	    udp_rtp_sender media;
 656	    media.ssrc = opt.ssrc;
 657	    media.pt = opt.pt;
 658	    media.payload_size = opt.payload_size;
 659	    media.mpegts_payload = opt.mpegts_payload;
 660	    apply_mcast_options(media, opt);
 661	
 662	    if (!media.open(opt.dst, opt.port)) {
 663	        return;
 664	    }
 665	
 666	    udp_rtp_sender fec_row;
 667	    udp_rtp_sender fec_col;
 668	
 669	    if (opt.fec) {
 670	        fec_row.ssrc = opt.fec_row_ssrc;
 671	        fec_row.pt = opt.fec_pt;
 672	        fec_row.payload_size = opt.payload_size;
 673	        fec_row.mpegts_payload = false;
 674	        apply_mcast_options(fec_row, opt);
 675	
 676	        fec_col.ssrc = opt.fec_col_ssrc;
 677	        fec_col.pt = opt.fec_pt;
 678	        fec_col.payload_size = opt.payload_size;
 679	        fec_col.mpegts_payload = false;
 680	        apply_mcast_options(fec_col, opt);
 681	
 682	        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
 683	            media.close();
 684	            return;
 685	        }
 686	
 687	        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
 688	            media.close();
 689	            fec_row.close();
 690	            return;
 691	        }
 692	    }
 693	
 694	    std::cerr
 695	        << "RTP media: " << opt.dst << ":" << opt.port
 696	        << " ssrc=" << opt.ssrc
 697	        << " pt=" << static_cast<int>(opt.pt)
 698	        << " bitrate=" << opt.bitrate_bps
 699	        << " payload=" << opt.payload_size
 700	        << " pps=" << packets_per_sec
 701	        << " ts_step=" << ts_step
 702	        << "\n";
 703	
 704	    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
 705	        std::cerr
 706	            << "multicast: ttl=" << opt.mcast_ttl
 707	            << " loop=" << opt.mcast_loop;
 708	
 709	        if (!opt.mcast_if.empty()) {
 710	            std::cerr << " if=" << opt.mcast_if;
 711	        } else {
 712	            std::cerr << " if=<route-default>";
 713	        }
 714	
 715	        std::cerr << "\n";
 716	    }
 717	
 718	    print_impairment(opt);
 719	
 720	    if (opt.fec) {
 721	        std::cerr
 722	            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
 723	            << " ssrc=" << opt.fec_row_ssrc
 724	            << " pt=" << static_cast<int>(opt.fec_pt)
 725	            << " L=" << opt.fec_l
 726	            << "\n";
 727	
 728	        std::cerr
 729	            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
 730	            << " ssrc=" << opt.fec_col_ssrc
 731	            << " pt=" << static_cast<int>(opt.fec_pt)
 732	            << " D=" << opt.fec_d
 733	            << "\n";
 734	    }
 735	
 736	    packet_scheduler scheduler(opt, [&media](packet value) {
 737	        media.send_packet(value);
 738	    });
 739	    packet_impairer impairment(opt, [&scheduler](packet value) {
 740	        scheduler.submit(std::move(value));
 741	    });
 742	
 743	    packet media_packet;
 744	
 745	    fec_state fec;
 746	    std::vector<std::uint8_t> fec_packet;
 747	
 748	    auto next = clock_type::now();
 749	
 750	    while (!g_stop) {
 751	        media.make_packet(media_packet);
 752	
 753	        if (opt.fec) {
 754	            xor_payload(fec.row_xor, media_packet);
 755	            xor_payload(fec.col_xor, media_packet);
 756	
 757	            ++fec.row_count;
 758	            ++fec.col_count;
 759	
 760	            if (fec.row_count >= opt.fec_l) {
 761	                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
 762	                fec_row.send_packet(fec_packet);
 763	
 764	                ++fec_row.seq;
 765	                fec_row.timestamp += ts_step * opt.fec_l;
 766	
 767	                fec.row_xor.clear();
 768	                fec.row_count = 0;
 769	            }
 770	
 771	            if (fec.col_count >= opt.fec_d) {
 772	                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
 773	                fec_col.send_packet(fec_packet);
 774	
 775	                ++fec_col.seq;
 776	                fec_col.timestamp += ts_step * opt.fec_d;
 777	
 778	                fec.col_xor.clear();
 779	                fec.col_count = 0;
 780	            }
 781	        }
 782	
 783	        scheduler.set_base_time(next);
 784	        impairment.submit(media_packet);
 785	
 786	        ++media.seq;
 787	        media.timestamp += ts_step;
 788	
 789	        next += interval;
 790	        std::this_thread::sleep_until(next);
 791	    }
 792	
 793	    impairment.flush();
 794	    media.close();
 795	
 796	    if (opt.fec) {
 797	        fec_row.close();
 798	        fec_col.close();
 799	    }
 800	}
