\};

bool impairment_enabled@enum class jitter_target_protocol {
    rtp,
    srt,
};

double jitter_target_gap_ms(
    jitter_target_protocol protocol,
    double nominal_interval_ms,
    double target_ms,
    bool high_phase)
{
    if (protocol == jitter_target_protocol::rtp) {
        if (target_ms <= nominal_interval_ms) {
            return nominal_interval_ms + (high_phase ? target_ms : -target_ms);
        }
        return high_phase ? target_ms * 2.0 : 0.0;
    }

    if (target_ms <= nominal_interval_ms * 2.0) {
        const double deviation_ms = target_ms / 2.0;
        return nominal_interval_ms + (high_phase ? deviation_ms : -deviation_ms);
    }
    return high_phase ? target_ms : 0.0;
}

class packet_scheduler {
public:
    packet_scheduler(
        const options& opt,
        packet_submitter send,
        double nominal_interval_ms,
        jitter_target_protocol target_protocol)
        : jitter_ms_(opt.jitter_ms)
        , jitter_target_ms_(opt.jitter_target_ms)
        , nominal_interval_ms_(nominal_interval_ms)
        , target_protocol_(target_protocol)
        , send_(std::move(send))
        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_) {}

    void set_base_time(clock_type::time_point value) {
        base_time_ = value;
    }

    void submit(packet value) {
        auto due = base_time_.value_or(clock_type::now());
        if (jitter_target_ms_ > 0.0) {
            if (last_due_) {
                due = *last_due_ + std::chrono::duration_cast<clock_type::duration>(
                    std::chrono::duration<double, std::milli>(next_target_gap_ms()));
            }
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (last_due_ && due < *last_due_) {
            due = *last_due_;
        }

        std::this_thread::sleep_until(due);
        send_(std::move(value));
        last_due_ = due;
    }

private:
    double next_target_gap_ms() {
        const double gap_ms = jitter_target_gap_ms(
            target_protocol_, nominal_interval_ms_, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return gap_ms;
    }

    double jitter_ms_{0.0};
    double jitter_target_ms_{0.0};
    double nominal_interval_ms_{0.0};
    jitter_target_protocol target_protocol_{jitter_target_protocol::rtp};
    packet_submitter send_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> jitter_distribution_;
    bool target_high_phase_{true};
    std::optional<clock_type::time_point> base_time_;
    std::optional<clock_type::time_point> last_due_;
};

