 829	
 830	            if (fec.row_count >= opt.fec_l) {
 831	                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
 832	                fec_row.send_packet(fec_packet);
 833	
 834	                ++fec_row.seq;
 835	                fec_row.timestamp += ts_step * opt.fec_l;
 836	
 837	                fec.row_xor.clear();
 838	                fec.row_count = 0;
 839	            }
 840	
 841	            if (fec.col_count >= opt.fec_d) {
 842	                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
 843	                fec_col.send_packet(fec_packet);
 844	
 845	                ++fec_col.seq;
 846	                fec_col.timestamp += ts_step * opt.fec_d;
 847	
 848	                fec.col_xor.clear();
 849	                fec.col_count = 0;
 850	            }
 851	        }
 852	
 853	        scheduler.set_base_time(next);
 854	        impairment.submit(media_packet);
 855	
 856	        ++media.seq;
 857	        media.timestamp += ts_step;
 858	
 859	        next += interval;
 860	        std::this_thread::sleep_until(next);
 861	    }
 862	
 863	    impairment.flush();
