 997	    void schedule(packet value) {
 998	        auto due = clock_type::now();
 999	        if (jitter_target_ms_ > 0.0) {
1000	            if (last_due_) {
1001	                due = *last_due_ + std::chrono::duration_cast<clock_type::duration>(
1002	                    std::chrono::duration<double, std::milli>(next_target_gap_ms()));
1003	            }
1004	        } else if (jitter_ms_ > 0.0) {
1005	            due += std::chrono::duration_cast<clock_type::duration>(
1006	                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
1007	        }
1008	
1009	        if (last_due_ && due < *last_due_) {
1010	            due = *last_due_;
1011	        }
1012	
1013	        scheduled_.emplace(due, std::move(value));
1014	        last_due_ = due;
1015	    }
