1018	        const double gap_ms = jitter_target_gap_ms(
1019	            jitter_target_protocol::srt,
1020	            nominal_interval_ms_,
1021	            jitter_target_ms_,
1022	            target_high_phase_);
1023	        target_high_phase_ = !target_high_phase_;
1024	        return gap_ms;
1025	    }
