 895	            return false;
 896	        }
 897	
 898	        std::memset(&destination_, 0, sizeof(destination_));
 899	        destination_.sin_family = AF_INET;
 900	        destination_.sin_port = htons(port);
 901	        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
 902	            std::cerr << "invalid SRT destination ip: " << dst << "\n";
 903	            close_fds();
 904	            return false;
 905	        }
 906	
 907	        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
