 175	std::optional<options> parse_args(int argc, char** argv) {
 176	    options opt;
 177	
 178	    try {
 179	        for (int i = 1; i < argc; ++i) {
 180	            std::string a = argv[i];
 181	
 182	            auto next = [&](const char* name) -> const char* {
 183	                if (!need_value(i, argc, name)) {
 184	                    return nullptr;
 185	                }
 186	                return argv[++i];
 187	            };
 188	
 189	            if (a == "--proto") {
 190	                const char* v = next("--proto");
 191	                if (!v) return std::nullopt;
 192	
 193	                std::string s = v;
 194	                if (s == "rtp") {
 195	                    opt.proto = proto_type::rtp;
 196	                } else if (s == "srt") {
 197	                    opt.proto = proto_type::srt;
 198	                } else {
 199	                    std::cerr << "invalid proto: " << s << "\n";
 200	                    return std::nullopt;
 201	                }
 202	            } else if (a == "--dst") {
 203	                const char* v = next("--dst");
 204	                if (!v) return std::nullopt;
 205	                opt.dst = v;
 206	            } else if (a == "--port") {
 207	                const char* v = next("--port");
 208	                if (!v) return std::nullopt;
 209	                opt.port = parse_u16(v, "--port");
 210	            } else if (a == "--bitrate") {
 211	                const char* v = next("--bitrate");
 212	                if (!v) return std::nullopt;
 213	                opt.bitrate_bps = static_cast<std::uint32_t>(std::stoul(v));
 214	            } else if (a == "--payload-size") {
 215	                const char* v = next("--payload-size");
