 312	    if (opt.payload_size == 0) {
 313	        std::cerr << "--payload-size must be greater than 0\n";
 314	        return std::nullopt;
 315	    }
 316	
 317	    if (opt.bitrate_bps == 0) {
 318	        std::cerr << "--bitrate must be greater than 0\n";
 319	        return std::nullopt;
 320	    }
 321	
 322	    const auto valid_rate = [](double value) {
 323	        return std::isfinite(value) && value >= 0.0 && value <= 1.0;
 324	    };
 325	
 326	    if (!valid_rate(opt.loss_rate) ||
 327	        !valid_rate(opt.duplicate_rate) ||
 328	        !valid_rate(opt.reorder_rate)) {
 329	        std::cerr << "--loss, --duplicate, and --reorder must be rates in 0..1\n";
 330	        return std::nullopt;
