 592	enum class jitter_target_protocol {
 593	    rtp,
 594	    srt,
 595	};
 596	
 597	double jitter_target_gap_ms(
 598	    jitter_target_protocol protocol,
 599	    double nominal_interval_ms,
 600	    double target_ms,
 601	    bool high_phase)
 602	{
 603	    if (protocol == jitter_target_protocol::rtp) {
 604	        if (target_ms <= nominal_interval_ms) {
 605	            return nominal_interval_ms + (high_phase ? target_ms : -target_ms);
 606	        }
 607	        return high_phase ? target_ms * 2.0 : 0.0;
 608	    }
 609	
 610	    if (target_ms <= nominal_interval_ms * 2.0) {
 611	        const double deviation_ms = target_ms / 2.0;
 612	        return nominal_interval_ms + (high_phase ? deviation_ms : -deviation_ms);
 613	    }
 614	    return high_phase ? target_ms : 0.0;
 615	}
