 704	void run_rtp(const options& opt) {
 705	    const double packets_per_sec =
 706	        static_cast<double>(opt.bitrate_bps) /
 707	        static_cast<double>(opt.payload_size * 8);
 708	
 709	    if (packets_per_sec <= 0.0) {
 710	        std::cerr << "invalid packets_per_sec\n";
 711	        return;
 712	    }
 713	
 714	    const auto interval = std::chrono::nanoseconds(
 715	        static_cast<long long>(1'000'000'000.0 / packets_per_sec));
 716	
 717	    const std::uint32_t ts_step =
 718	        static_cast<std::uint32_t>(
 719	            static_cast<double>(opt.clock_rate) / packets_per_sec);
 720	
 721	    udp_rtp_sender media;
 722	    media.ssrc = opt.ssrc;
 723	    media.pt = opt.pt;
 724	    media.payload_size = opt.payload_size;
 725	    media.mpegts_payload = opt.mpegts_payload;
 726	    apply_mcast_options(media, opt);
 727	
 728	    if (!media.open(opt.dst, opt.port)) {
 729	        return;
 730	    }
 731	
 732	    udp_rtp_sender fec_row;
 733	    udp_rtp_sender fec_col;
 734	
 735	    if (opt.fec) {
 736	        fec_row.ssrc = opt.fec_row_ssrc;
 737	        fec_row.pt = opt.fec_pt;
 738	        fec_row.payload_size = opt.payload_size;
 739	        fec_row.mpegts_payload = false;
 740	        apply_mcast_options(fec_row, opt);
 741	
 742	        fec_col.ssrc = opt.fec_col_ssrc;
 743	        fec_col.pt = opt.fec_pt;
 744	        fec_col.payload_size = opt.payload_size;
 745	        fec_col.mpegts_payload = false;
 746	        apply_mcast_options(fec_col, opt);
 747	
 748	        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
 749	            media.close();
 750	            return;
 751	        }
 752	
 753	        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
 754	            media.close();
 755	            fec_row.close();
 756	            return;
 757	        }
 758	    }
 759	
 760	    std::cerr
 825	            xor_payload(fec.col_xor, media_packet);
 826	
 827	            ++fec.row_count;
 828	            ++fec.col_count;
 829	
 830	            if (fec.row_count >= opt.fec_l) {
 831	                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
 832	                fec_row.send_packet(fec_packet);
 833	
 834	                ++fec_row.seq;
 835	                fec_row.timestamp += ts_step * opt.fec_l;
 836	
 837	                fec.row_xor.clear();
 838	                fec.row_count = 0;
 839	            }
 840	
 841	            if (fec.col_count >= opt.fec_d) {
 842	                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
 843	                fec_col.send_packet(fec_packet);
 844	
 845	                ++fec_col.seq;
 846	                fec_col.timestamp += ts_step * opt.fec_d;
 847	
 848	                fec.col_xor.clear();
 849	                fec.col_count = 0;
 850	            }
 851	        }
 852	
 853	        scheduler.set_base_time(next);
 854	        impairment.submit(media_packet);
 855	
 856	        ++media.seq;
 857	        media.timestamp += ts_step;
 858	
 859	        next += interval;
 860	        std::this_thread::sleep_until(next);
 861	    }
 862	
 863	    impairment.flush();
 864	    media.close();
 865	
 866	    if (opt.fec) {
 867	        fec_row.close();
 868	        fec_col.close();
 869	    }
 870	}
