 891	    bool open(const std::string& dst, std::uint16_t port) {
 892	        downstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
 893	        if (downstream_fd_ < 0) {
 894	            perror("SRT proxy downstream socket");
 895	            return false;
 896	        }
 897	
 898	        std::memset(&destination_, 0, sizeof(destination_));
 899	        destination_.sin_family = AF_INET;
 900	        destination_.sin_port = htons(port);
 901	        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
 902	            std::cerr << "invalid SRT destination ip: " << dst << "\n";
 903	            close_fds();
 904	            return false;
 905	        }
 906	
 907	        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
 908	        if (upstream_fd_ < 0) {
 909	            perror("SRT proxy upstream socket");
 910	            close_fds();
 911	            return false;
 912	        }
 913	
 914	        sockaddr_in listen{};
 915	        listen.sin_family = AF_INET;
 916	        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
 917	        listen.sin_port = 0;
 918	        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
 919	            perror("SRT proxy bind");
 920	            close_fds();
 921	            return false;
 922	        }
 923	
 924	        socklen_t length = sizeof(listen);
 925	        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
 926	            perror("SRT proxy getsockname");
 927	            close_fds();
 928	            return false;
 929	        }
 930	
 931	        local_port_ = ntohs(listen.sin_port);
 932	        return true;
 933	    }
