 956	    void close_fds() {
 957	        if (upstream_fd_ >= 0) {
 958	            ::close(upstream_fd_);
 959	            upstream_fd_ = -1;
 960	        }
 961	        if (downstream_fd_ >= 0) {
 962	            ::close(downstream_fd_);
 963	            downstream_fd_ = -1;
 964	        }
 965	    }
