    98	    const thresholdSeries = displayThresholds.map((threshold) => ({
    99	      label: threshold.label,
   100	      stroke: resolveColor(hostRef.current!, thresholdColor(threshold.severity), lineColor),
   101	      width: threshold.recovery ? 1 : 1.5,
