     4	import { formatFixedNumber, formatMetricAxisValue, formatMetricValue, metricDisplayScale, niceLinearRange, type MetricDisplayScale } from "./format";
     5	
     6	type MetricChartProps = {
     7	  title: string;
     8	  metric?: TimeSeriesMetric;
     9	  height?: number;
    10	  color?: string;
