    40	type DrawThresholdLabel = ChartThreshold & { color: string };
    41	
    42	const syncKey = "stream-detail";
    43	const chartMetricValueFields = new Set(["value", "bps", "pps", "seconds", "avg", "min", "max", "window", "total"]);
    44	
    45	export function MetricChart({ title, metric, height = 190, color = "var(--chart-accent)", compact = false, fillHeight = false, alertContext, yScale, scalePreference }: MetricChartProps) {
    46	  const hostRef = useRef<HTMLDivElement | null>(null);
    47	  const chartRef = useRef<uPlot | null>(null);
    48	  const hostVisibleRef = useRef(false);
    49	  const chartStateRef = useRef<{
    50	    metric?: TimeSeriesMetric;
    51	    yRange: { min: number; max: number; splits: number[] };
    52	    displayScale: MetricDisplayScale;
    53	    displayThresholds: ChartThreshold[];
    54	    axisDigits: number;
    55	  } | null>(null);
    56	  const [cursorPoint, setCursorPoint] = useState<MetricPoint | null>(null);
    57	  const hasData = Boolean(metric && metric.points.length > 0);
    58	  const thresholds = useMemo(() => thresholdsForMetric(metric, alertContext), [metric, alertContext]);
    59	  const rawValues = useMemo(() => chartValues(metric, thresholds), [metric, thresholds]);
    60	  const displayScale = useMemo(() => metricDisplayScale(metric?.key, metric?.unit, rawValues, scalePreference),  [metric?.key, metric?.unit, rawValues, scalePreference]);
    61	  const yRange = useMemo(() => {
    62	    const values = rawValues.map((value) => value / displayScale.divisor);
    63	    if (yScale?.mode === "fixed" && Number.isFinite(yScale.min) && Number.isFinite(yScale.max) && yScale.min! < yScale.max!) {
    64	      const min = yScale.min! / displayScale.divisor;
    65	      const max = yScale.max! / displayScale.divisor;
    66	      return { min, max, splits: niceLinearRange([min, max], false).splits.filter((value) => value >= min && value <= max) };
    67	    }
    68	    return niceLinearRange(values, yScale?.mode === "zero" || displayScale.includeZero);
    69	  }, [rawValues, displayScale, yScale]);
    70	  const displayThresholds = useMemo(() => thresholds.map((threshold) => ({ ...threshold, value: threshold.value / displayScale.divisor })), [thresholds, displayScale]);
    71	  const thresholdStyleSignature = thresholds.map((threshold) => [threshold.id, threshold.metric, threshold.severity, threshold.recovery].join(":" )).join("|");
    72	  const theme = document.documentElement.dataset.theme ?? "light";
    73	  const initialAxisWidth = chartAxisWidth(Math.max(1, hostRef.current?.clientWidth || 640));
    74	  const axisDigits = chartAxisFractionDigits(yRange.splits, displayScale, initialAxisWidth);
    75	  chartStateRef.current = { metric, yRange, displayScale, displayThresholds, axisDigits };
    76	
    77	  useEffect(() => {
    78	    if (!hostRef.current || !metric || metric.points.length === 0) return;
    79	
    80	    const host = hostRef.current;
    81	    hostVisibleRef.current = isVisibleInViewport(host);
    82	    const styles = getComputedStyle(hostRef.current);
    83	    const lineColor = resolveColor(hostRef.current, color, cssVar(styles, "--chart-accent", cssVar(styles, "--accent", "currentColor")));
    84	    const axisColor = cssVar(styles, "--chart-axis", cssVar(styles, "--muted", "currentColor"));
    85	    const gridColor = cssVar(styles, "--chart-grid", "transparent");
    86	    const bandFill = toRgba(lineColor, compact ? 0.18 : 0.24);
    87	    const rangeStroke = toRgba(lineColor, compact ? 0.28 : 0.34);
    88	    const labelBackground = toRgba(cssVar(styles, "--surface", "#ffffff"), compact ? 0.82 : 0.9);
    89	    const thresholdColors = new Map(displayThresholds.map((threshold) => [threshold.id, resolveColor(host, thresholdColor(threshold.severity), lineColor)]));
    90	    const thresholdLabels = (): DrawThresholdLabel[] => (chartStateRef.current?.displayThresholds ?? []).map((threshold) => ({
    91	      ...threshold,
    92	      color: thresholdColors.get(threshold.id) ?? lineColor
    93	    }));
    94	    const chartHeight = chartHeightFor(hostRef.current, height, fillHeight);
    95	    const chartWidth = Math.max(1, host.clientWidth || 640);
    96	    const axisWidth = chartAxisWidth(chartWidth);
    97	    chartStateRef.current = { metric, yRange, displayScale, displayThresholds, axisDigits: chartAxisFractionDigits(yRange.splits, displayScale, axisWidth) };
    98	    const thresholdSeries = displayThresholds.map((threshold) => ({
    99	      label: threshold.label,
   100	      stroke: resolveColor(hostRef.current!, thresholdColor(threshold.severity), lineColor),
   101	      width: threshold.recovery ? 1 : 1.5,
   102	      dash: threshold.recovery ? [5, 4] : undefined,
   103	      points: { show: false }
   104	    }));
   105	    const options: uPlot.Options = {
   106	      width: chartWidth,
   107	      height: chartHeight,
   108	      cursor: { sync: { key: syncKey } },
   109	      scales: { x: { time: true }, y: { auto: false, range: () => [chartStateRef.current!.yRange.min, chartStateRef.current!.yRange.max] } },
   110	      legend: { show: false },
   111	      hooks: {
   112	        draw: [(chart) => drawThresholdLabels(chart, thresholdLabels(), chartStateRef.current?.displayScale.unit, labelBackground, compact)],
   113	        setCursor: [(chart) => {
   114	          if (chart.cursor.idx == null || !hostRef.current || !hostVisibleRef.current) {
   115	            setCursorPoint(null);
   116	            return;
   117	          }
   118	          const point = chartStateRef.current?.metric?.points[chart.cursor.idx];
   119	          if (!point) {
   120	            setCursorPoint(null);
   121	            return;
   122	          }
   123	          setCursorPoint(point);
   124	        }]
   125	      },
   126	      axes: compact
   127	        ? [
   128	            { show: false },
   129	            { show: false }
   130	          ]
   131	        : [
   132	            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor }, values: (_u, values) => values.map((v) => formatChartAxisTime(v)) },
   133	            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor }, size: axisWidth, splits: () => chartStateRef.current!.yRange.splits, values: (_u, values) => values.map((v) => formatMetricAxisValue(v, chartStateRef.current!.displayScale, chartStateRef.current!.axisDigits)) }
   134	          ],
   135	      series: [
   136	        {},
   137	        {
   138	          label: "min",
   139	          stroke: rangeStroke,
   140	          width: 1,
   141	          points: { show: false }
   142	        },
   143	        {
   144	          label: "max",
   145	          stroke: rangeStroke,
   146	          width: 1,
   147	          points: { show: false }
   148	        },
   149	        { label: "avg", stroke: lineColor, width: compact ? 1.3 : 2, points: { show: false } },
   150	        ...thresholdSeries
   151	      ],
   152	      bands: [{ series: [2, 1], fill: bandFill }],
   153	      padding: compact ? [6, 4, 4, 4] : undefined
   154	    } as uPlot.Options;
   155	
   156	    chartRef.current?.destroy();
   157	    chartRef.current = new uPlot(options, toUplotData(metric, displayThresholds, displayScale.divisor), host);
   158	
   159	    const resize = () => {
   160	      if (hostRef.current && chartRef.current) {
   161	        const width = Math.max(1, hostRef.current.clientWidth);
   162	        chartRef.current.setSize({
   163	          width,
   164	          height: chartHeightFor(hostRef.current, height, fillHeight)
   165	        });
   166	      }
   167	    };
   168	    const resizeObserver = new ResizeObserver(() => resize());
   169	    resizeObserver.observe(host);
   170	    const visibilityObserver = new IntersectionObserver(([entry]) => {
   171	      hostVisibleRef.current = entry.isIntersecting;
   172	      if (!hostVisibleRef.current) setCursorPoint(null);
   173	    });
   174	    visibilityObserver.observe(host);
   175	    window.addEventListener("resize", resize);
   176	    return () => {
   177	      resizeObserver.disconnect();
   178	      visibilityObserver.disconnect();
   179	      window.removeEventListener("resize", resize);
   180	      chartRef.current?.destroy();
   181	      chartRef.current = null;
   182	    };
   183	  }, [metric?.key, hasData, height, color, compact, fillHeight, thresholdStyleSignature, theme]);
   184	
   185	  useEffect(() => {
