   187	    chartRef.current.setData(toUplotData(metric, displayThresholds, displayScale.divisor));
   188	    chartRef.current.setScale("y", { min: yRange.min, max: yRange.max });
   189	  }, [metric, displayThresholds, displayScale.divisor, yRange.min, yRange.max]);
   190	
   191	  return (
   192	    <section className={`chart-card ${compact ? "compact-chart" : ""}`}>
   193	      <div className="chart-header">
   194	        <h3>{title}</h3>
   195	        <div className="chart-header-meta">
   196	          <div className={"chart-header-values " + (cursorPoint ? "is-active" : "is-idle")} aria-hidden="true">
   197	            {!compact && <strong>{cursorPoint ? formatChartTime(cursorPoint.time) : "\u00a0"}</strong>}
   198	            {!compact && <span>min <b>{cursorPoint ? formatChartValue(cursorPoint.min ?? cursorPoint.avg ?? cursorPoint.value, displayScale, false) : "—"}</b></span>}
   199	            <span>avg <b>{cursorPoint ? formatChartValue(cursorPoint.avg ?? cursorPoint.value, displayScale, compact) : "—"}</b></span>
   200	            {!compact && <span>max <b>{cursorPoint ? formatChartValue(cursorPoint.max ?? cursorPoint.avg ?? cursorPoint.value, displayScale, false) : "—"}</b></span>}
   201	          </div>
   202	          {!compact && <span className="chart-header-unit">{displayScale.unit}</span>}
   203	        </div>
   204	      </div>
   205	      <div
   206	        className={`chart-host ${compact ? "compact-grid-host" : ""}`}
   207	        ref={hostRef}
