   215	function thresholdsForMetric(metric: TimeSeriesMetric | undefined, context: ChartAlertContext | undefined): ChartThreshold[] {
   216	  if (!metric || !context) return [];
   217	  return context.rules.flatMap((rule) => {
   218	    if (rule.enabled === false || (rule.type ?? "threshold") !== "threshold") return [];
   219	    const target = rule.target ?? "any";
   220	    if (target !== "any" && target !== context.target) return [];
   221	    if (context.proto && rule.proto && rule.proto !== context.proto) return [];
   222	    if (metricKeyForAlert(rule.metric) !== metric.key || !Number.isFinite(rule.error_threshold)) return [];
   223	    const severity = rule.severity ?? "warning";
   224	    const operator = rule.operator ?? ">";
   225	    const result: ChartThreshold[] = [{ id: rule.id, metric: rule.metric, operator, label: `${rule.id} trigger`, value: rule.error_threshold!, severity, recovery: false }];
   226	    if (Number.isFinite(rule.recover_threshold) && Math.abs(rule.recover_threshold! - rule.error_threshold!) > Number.EPSILON) {
   227	      result.push({ id: rule.id + ":recovery", metric: rule.metric, operator, label: `${rule.id} recovery`, value: rule.recover_threshold!, severity, recovery: true });
   228	    }
   229	    return result;
   230	  });
   231	}
   232	
   233	function metricKeyForAlert(key: string) {
   234	  const parts = key.split(".");
   235	  return chartMetricValueFields.has(parts.at(-1) ?? "") ? parts.slice(0, -1).join(".") : key;
   236	}
   237	
   238	function thresholdColor(severity: string) {
   239	  if (severity === "critical" || severity === "error") return "var(--error)";
   240	  if (severity === "warning") return "var(--warning)";
   241	  return "var(--accent)";
   242	}
   243	
   244	function drawThresholdLabels(chart: uPlot, thresholds: DrawThresholdLabel[], unit: string | undefined, background: string, compact: boolean) {
   245	  if (thresholds.length === 0) return;
   246	  const ratio = uPlot.pxRatio;
   247	  const fontSize = (compact ? 9 : 10) * ratio;
   248	  const labelHeight = (compact ? 13 : 16) * ratio;
   249	  const gap = 3 * ratio;
   250	  const padding = 4 * ratio;
   251	  const { left, top, width, height } = chart.bbox;
   252	  const entries = thresholds
   253	    .map((threshold) => ({
   254	      threshold,
   255	      text: threshold.metric + " " + (threshold.recovery ? "recovery" : threshold.operator) + " " + formatFixedNumber(threshold.value) + (unit ? " " + unit : ""),
   256	      y: chart.valToPos(threshold.value, "y", true)
   257	    }))
   258	    .filter((entry) => entry.y >= top && entry.y <= top + height)
   259	    .sort((a, b) => a.y - b.y);
