   103	std::uint16_t parse_u16(const char* s, const char* name) {
   104	    const auto v = std::stoul(s);
   105	    if (v > 65535) {
   106	        throw std::runtime_error(std::string(name) + " out of range: " + s);
   107	    }
   108	    return static_cast<std::uint16_t>(v);
   109	}
