   361	struct udp_rtp_sender {
   362	    int fd{-1};
   363	    sockaddr_in addr{};
   364	
   365	    std::uint32_t ssrc{0};
   366	    std::uint8_t pt{33};
   367	    std::uint16_t seq{0};
   368	    std::uint32_t timestamp{0};
   369	
   370	    std::size_t payload_size{1316};
   371	    bool mpegts_payload{false};
   372	
   373	    std::string mcast_if{};
   374	    int mcast_ttl{1};
   375	    int mcast_loop{1};
   376	
   377	    bool open(const std::string& ip, std::uint16_t port) {
   378	        fd = ::socket(AF_INET, SOCK_DGRAM, 0);
   379	        if (fd < 0) {
   380	            perror("socket");
   381	            return false;
   382	        }
   383	
   384	        std::memset(&addr, 0, sizeof(addr));
   385	        addr.sin_family = AF_INET;
   386	        addr.sin_port = htons(port);
   387	
   388	        if (::inet_pton(AF_INET, ip.c_str(), &addr.sin_addr) != 1) {
   389	            std::cerr << "invalid ip: " << ip << "\n";
   390	            return false;
   391	        }
   392	
   393	        if (is_ipv4_multicast_addr(addr.sin_addr)) {
   394	            if (!configure_multicast()) {
   395	                return false;
   396	            }
   397	        }
   398	
   399	        return true;
   400	    }
   401	
   402	    bool configure_multicast() {
   403	        const unsigned char ttl = static_cast<unsigned char>(mcast_ttl);
   404	        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
   405	            perror("setsockopt IP_MULTICAST_TTL");
   406	            return false;
   407	        }
   408	
   409	        const unsigned char loop = static_cast<unsigned char>(mcast_loop != 0);
   410	        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_LOOP, &loop, sizeof(loop)) < 0) {
   411	            perror("setsockopt IP_MULTICAST_LOOP");
   412	            return false;
   413	        }
   414	
   415	        if (!mcast_if.empty()) {
   416	            in_addr local_if{};
   417	            if (::inet_pton(AF_INET, mcast_if.c_str(), &local_if) != 1) {
   418	                std::cerr << "invalid --mcast-if: " << mcast_if << "\n";
   419	                return false;
   420	            }
   421	
   422	            if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_IF, &local_if, sizeof(local_if)) < 0) {
   423	                perror("setsockopt IP_MULTICAST_IF");
   424	                return false;
   425	            }
   426	        }
   427	
   428	        return true;
   429	    }
   430	
   431	    void close() {
   432	        if (fd >= 0) {
   433	            ::close(fd);
   434	            fd = -1;
   435	        }
   436	    }
   437	
   438	    void make_packet(std::vector<std::uint8_t>& out) {
   439	        out.resize(12 + payload_size);
   440	
   441	        out[0] = 0x80;          // V=2, P=0, X=0, CC=0
   442	        out[1] = pt & 0x7f;     // M=0, PT
   443	
   444	        put_u16_be(&out[2], seq);
   445	        put_u32_be(&out[4], timestamp);
   446	        put_u32_be(&out[8], ssrc);
   447	
   448	        auto* payload = out.data() + 12;
   449	
   450	        if (mpegts_payload) {
   451	            // MPEG-TS風ダミーpayload。
   452	            // 188 byteごとにsync byte 0x47を置くだけなので、再生可能なTSではない。
   453	            for (std::size_t i = 0; i < payload_size; ++i) {
   454	                payload[i] = (i % 188 == 0)
   455	                    ? 0x47
   456	                    : static_cast<std::uint8_t>((seq + i) & 0xff);
   457	            }
   458	        } else {
   459	            for (std::size_t i = 0; i < payload_size; ++i) {
   460	                payload[i] = static_cast<std::uint8_t>((seq + i) & 0xff);
   461	            }
   462	        }
   463	    }
   464	
   465	    void send_packet(const std::vector<std::uint8_t>& packet) {
   466	        const auto n = ::sendto(
   467	            fd,
   468	            packet.data(),
   469	            packet.size(),
   470	            0,
   471	            reinterpret_cast<const sockaddr*>(&addr),
   472	            sizeof(addr));
   473	
   474	        if (n < 0) {
   475	            perror("sendto");
   476	        }
   477	    }
   478	};
