   488	void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
   489	    constexpr std::size_t header_size = 12;
   490	
   491	    if (rtp_packet.size() < header_size) {
   492	        return;
   493	    }
   494	
   495	    const std::size_t payload_len = rtp_packet.size() - header_size;
   496	
   497	    if (acc.empty()) {
   498	        acc.assign(payload_len, 0);
   499	    }
   500	
   501	    const auto n = std::min(acc.size(), payload_len);
   502	    for (std::size_t i = 0; i < n; ++i) {
   503	        acc[i] ^= rtp_packet[header_size + i];
   504	    }
   505	}
