   597	double jitter_target_gap_ms(
   598	    jitter_target_protocol protocol,
   599	    double nominal_interval_ms,
   600	    double target_ms,
   601	    bool high_phase)
   602	{
   603	    if (protocol == jitter_target_protocol::rtp) {
   604	        if (target_ms <= nominal_interval_ms) {
   605	            return nominal_interval_ms + (high_phase ? target_ms : -target_ms);
   606	        }
