   617	class packet_scheduler {
   618	public:
   619	    packet_scheduler(
   620	        const options& opt,
   621	        packet_submitter send,
   622	        double nominal_interval_ms,
   623	        jitter_target_protocol target_protocol)
   624	        : jitter_ms_(opt.jitter_ms)
   625	        , jitter_target_ms_(opt.jitter_target_ms)
   626	        , nominal_interval_ms_(nominal_interval_ms)
   627	        , target_protocol_(target_protocol)
   628	        , send_(std::move(send))
   629	        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
   630	        , jitter_distribution_(0.0, jitter_ms_) {}
   631	
   632	    void set_base_time(clock_type::time_point value) {
   633	        base_time_ = value;
   634	    }
   635	
   636	    void submit(packet value) {
   637	        auto due = base_time_.value_or(clock_type::now());
   638	        if (jitter_target_ms_ > 0.0) {
   639	            if (last_due_) {
   640	                due = *last_due_ + std::chrono::duration_cast<clock_type::duration>(
   641	                    std::chrono::duration<double, std::milli>(next_target_gap_ms()));
   642	            }
   643	        } else if (jitter_ms_ > 0.0) {
   644	            due += std::chrono::duration_cast<clock_type::duration>(
   645	                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
   646	        }
   647	
   648	        if (last_due_ && due < *last_due_) {
   649	            due = *last_due_;
   650	        }
   651	
   652	        std::this_thread::sleep_until(due);
   653	        send_(std::move(value));
   654	        last_due_ = due;
   655	    }
   656	
   657	private:
   658	    double next_target_gap_ms() {
   659	        const double gap_ms = jitter_target_gap_ms(
   660	            target_protocol_, nominal_interval_ms_, jitter_target_ms_, target_high_phase_);
   661	        target_high_phase_ = !target_high_phase_;
   662	        return gap_ms;
   663	    }
   664	
   665	    double jitter_ms_{0.0};
   666	    double jitter_target_ms_{0.0};
   667	    double nominal_interval_ms_{0.0};
   668	    jitter_target_protocol target_protocol_{jitter_target_protocol::rtp};
   669	    packet_submitter send_;
   670	    std::mt19937 rng_;
   671	    std::uniform_real_distribution<double> jitter_distribution_;
   672	    bool target_high_phase_{true};
   673	    std::optional<clock_type::time_point> base_time_;
   674	    std::optional<clock_type::time_point> last_due_;
   675	};
