const r = await tools.exec_command({"cmd":"run_measure() {
  local measure_port="$1"
  shift
  perl -MIO::Socket::INET -MIO::Select -MTime::HiRes=time -e '
    my $port = shift;
    my $socket = IO::Socket::INET->new(LocalAddr => "127.0.0.1", LocalPort => $port, Proto => "udp", ReuseAddr => 1) or die $!;
    my $select = IO::Select->new($socket);
    my ($packets, $bytes) = (0, 0);
    my $end = time + 3.0;
    while (time < $end) {
      my @ready = $select->can_read($end - time);
      for my $fh (@ready) { my $data = q{}; $fh->recv($data, 65536); ++$packets; $bytes += length $data; }
    }
    printf "packets=%d payload_bps=%.0f wire_bps=%.0f\n", $packets, $bytes * 8 / 3.0, ($bytes + 28 * $packets) * 8 / 3.0;
  ' "$measure_port" &
  local receiver_pid=$!
  sleep 0.1
  timeout -s INT 3 /tmp/streamgen-jitter-rate --proto rtp --dst 127.0.0.1 --port "$measure_port" --bitrate 1000000 "$@" >/tmp/streamgen-rate.out 2>&1 || true
  wait "$receiver_pid"
}
