using packet = std::vector<std::uint8_t>;
using packet_submitter = std::function<void(packet)>;

class packet_impairer {
public:
    packet_impairer(const options& opt, packet_submitter submit)
        : loss_rate_(opt.loss_rate)
        , duplicate_rate_(opt.duplicate_rate)
        , reorder_rate_(opt.reorder_rate)
        , submit_(std::move(submit))
        , rng_(opt.seed ? *opt.seed : std::random_device{}()) {}

    void submit(packet value) {
        const bool drop = hit(loss_rate_);
        const bool duplicate = hit(duplicate_rate_);
        const bool reorder = hit(reorder_rate_);

        if (delayed_) {
            if (!drop) {
                submit_with_duplicate(std::move(value), duplicate);
            }
            submit_(std::move(*delayed_));
            delayed_.reset();
            return;
        }

        if (drop) {
            return;
        }

        if (reorder) {
            delayed_ = std::move(value);
            return;
        }

        submit_with_duplicate(std::move(value), duplicate);
    }

    void flush() {
        if (delayed_) {
            submit_(std::move(*delayed_));
            delayed_.reset();
        }
    }

private:
    bool hit(double rate) {
        return rate > 0.0 && distribution_(rng_) < rate;
    }

    void submit_with_duplicate(packet value, bool duplicate) {
        if (duplicate) {
            submit_(value);
        }
        submit_(std::move(value));
    }

    double loss_rate_{0.0};
    double duplicate_rate_{0.0};
    double reorder_rate_{0.0};
    packet_submitter submit_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::optional<packet> delayed_;
};

enum class jitter_target_protocol {
    rtp,
    srt,
};

double jitter_target_offset_ms(
    jitter_target_protocol protocol,
    double target_ms,
    bool high_phase)
{
    if (!high_phase) return 0.0;
    return protocol == jitter_target_protocol::rtp ? target_ms : target_ms / 2.0;
}

class packet_scheduler {
public:
    packet_scheduler(
        const options& opt,
        packet_submitter send,
        jitter_target_protocol target_protocol)
        : jitter_ms_(opt.jitter_ms)
        , jitter_target_ms_(opt.jitter_target_ms)
        , target_protocol_(target_protocol)
        , send_(std::move(send))
        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_) {}

    void set_base_time(clock_type::time_point value) {
        base_time_ = value;
    }

    void submit(packet value) {
        auto due = base_time_.value_or(clock_type::now());
        if (jitter_target_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (last_due_ && due < *last_due_) {
            due = *last_due_;
        }

        std::this_thread::sleep_until(due);
        send_(std::move(value));
        last_due_ = due;
    }

private:
    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            target_protocol_, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    double jitter_ms_{0.0};
    double jitter_target_ms_{0.0};
    jitter_target_protocol target_protocol_{jitter_target_protocol::rtp};
    packet_submitter send_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> jitter_distribution_;
    bool target_high_phase_{false};
    std::optional<clock_type::time_point> base_time_;
    std::optional<clock_type::time_point> last_due_;
};

bool impairment_enabled(const options& opt) {
    return opt.loss_rate > 0.0 ||
           opt.duplicate_rate > 0.0 ||
           opt.reorder_rate > 0.0 ||
           opt.jitter_ms > 0.0 ||
        static_cast<double>(opt.bitrate_bps) /
        static_cast<double>(opt.payload_size * 8);

    if (packets_per_sec <= 0.0) {
        std::cerr << "invalid packets_per_sec\n";
        return;
    }

    const auto interval = std::chrono::nanoseconds(
        static_cast<long long>(1'000'000'000.0 / packets_per_sec));

    const std::uint32_t ts_step =
        static_cast<std::uint32_t>(
            static_cast<double>(opt.clock_rate) / packets_per_sec);

    udp_rtp_sender media;
    media.ssrc = opt.ssrc;
    media.pt = opt.pt;
    media.payload_size = opt.payload_size;
    media.mpegts_payload = opt.mpegts_payload;
    apply_mcast_options(media, opt);

    if (!media.open(opt.dst, opt.port)) {
        return;
    }

    udp_rtp_sender fec_row;
    udp_rtp_sender fec_col;

    if (opt.fec) {
        fec_row.ssrc = opt.fec_row_ssrc;
        fec_row.pt = opt.fec_pt;
        fec_row.payload_size = opt.payload_size;
        fec_row.mpegts_payload = false;
        apply_mcast_options(fec_row, opt);

        fec_col.ssrc = opt.fec_col_ssrc;
        fec_col.pt = opt.fec_pt;
        fec_col.payload_size = opt.payload_size;
        fec_col.mpegts_payload = false;
        apply_mcast_options(fec_col, opt);

        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
            media.close();
            return;
        }

        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
            media.close();
            fec_row.close();
            return;
        }
    }

    std::cerr
        << "RTP media: " << opt.dst << ":" << opt.port
        << " ssrc=" << opt.ssrc
        << " pt=" << static_cast<int>(opt.pt)
        << " bitrate=" << opt.bitrate_bps
        << " payload=" << opt.payload_size
        << " pps=" << packets_per_sec
        << " ts_step=" << ts_step
        << "\n";

    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
        std::cerr
            << "multicast: ttl=" << opt.mcast_ttl
            << " loop=" << opt.mcast_loop;

        if (!opt.mcast_if.empty()) {
            std::cerr << " if=" << opt.mcast_if;
        } else {
            std::cerr << " if=<route-default>";
        }

        std::cerr << "\n";
    }

    print_impairment(opt);

    if (opt.fec) {
        std::cerr
            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
            << " ssrc=" << opt.fec_row_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " L=" << opt.fec_l
            << "\n";

        std::cerr
            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
            << " ssrc=" << opt.fec_col_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " D=" << opt.fec_d
            << "\n";
    }

    packet_scheduler scheduler(
        opt,
        [&media](packet value) { media.send_packet(value); },
        jitter_target_protocol::rtp);
    packet_impairer impairment(opt, [&scheduler](packet value) {
        scheduler.submit(std::move(value));
    });

    packet media_packet;

    fec_state fec;
    std::vector<std::uint8_t> fec_packet;

    auto next = clock_type::now();

    while (!g_stop) {
        media.make_packet(media_packet);

        if (opt.fec) {
            xor_payload(fec.row_xor, media_packet);
            xor_payload(fec.col_xor, media_packet);

            ++fec.row_count;
            ++fec.col_count;

            if (fec.row_count >= opt.fec_l) {
                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
                fec_row.send_packet(fec_packet);

                ++fec_row.seq;
                fec_row.timestamp += ts_step * opt.fec_l;

                fec.row_xor.clear();
                fec.row_count = 0;
            }

            if (fec.col_count >= opt.fec_d) {
                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
                fec_col.send_packet(fec_packet);

                ++fec_col.seq;
                fec_col.timestamp += ts_step * opt.fec_d;

                fec.col_xor.clear();
                fec.col_count = 0;
            }
        }

        scheduler.set_base_time(next);
        impairment.submit(media_packet);

        ++media.seq;
        media.timestamp += ts_step;

        next += interval;
        std::this_thread::sleep_until(next);
    }

    impairment.flush();
    media.close();

    if (opt.fec) {
        fec_row.close();
        fec_col.close();
    }
}

#ifdef ENABLE_SRT
class srt_impairment_proxy {
public:
    explicit srt_impairment_proxy(const options& opt)
        : jitter_ms_(opt.jitter_ms)
        , jitter_target_ms_(opt.jitter_target_ms)
        , nominal_interval_ms_(
            1000.0 * static_cast<double>(opt.payload_size) * 8.0 /
            static_cast<double>(opt.bitrate_bps))
        , rng_(opt.seed ? (*opt.seed ^ 0x85ebca6bU) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , impairment_(opt, [this](packet value) {
            schedule(std::move(value));
        }) {}

    ~srt_impairment_proxy() {
        stop();
    }

    bool open(const std::string& dst, std::uint16_t port) {
        downstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (downstream_fd_ < 0) {
            perror("SRT proxy downstream socket");
            return false;
        }

        std::memset(&destination_, 0, sizeof(destination_));
        destination_.sin_family = AF_INET;
        destination_.sin_port = htons(port);
        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
            std::cerr << "invalid SRT destination ip: " << dst << "\n";
            close_fds();
            return false;
        }

        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (upstream_fd_ < 0) {
            perror("SRT proxy upstream socket");
            close_fds();
            return false;
        }

        sockaddr_in listen{};
        listen.sin_family = AF_INET;
        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        listen.sin_port = 0;
        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
            perror("SRT proxy bind");
            close_fds();
            return false;
        }

        socklen_t length = sizeof(listen);
        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
            perror("SRT proxy getsockname");
            close_fds();
            return false;
        }

        local_port_ = ntohs(listen.sin_port);
        return true;
    }

    void start() {
        worker_ = std::thread([this] { run(); });
    }

    void stop() {
        stopping_ = true;
        if (worker_.joinable()) {
            worker_.join();
        }
        close_fds();
    }

    std::uint16_t local_port() const {
        return local_port_;
    }

private:
    static bool is_data_packet(const packet& value) {
        return value.size() >= 16 && (value[0] & 0x80U) == 0;
    }

    void close_fds() {
        if (upstream_fd_ >= 0) {
            ::close(upstream_fd_);
            upstream_fd_ = -1;
        }
        if (downstream_fd_ >= 0) {
            ::close(downstream_fd_);
            downstream_fd_ = -1;
        }
    }

    void send_downstream(const packet& value) {
        const auto sent = ::sendto(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&destination_),
            sizeof(destination_));
        if (sent < 0) {
            perror("SRT proxy send downstream");
        }
    }

    void send_upstream(const packet& value) {
        if (!has_sender_) {
            return;
        }

        const auto sent = ::sendto(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&sender_),
            sender_length_);
        if (sent < 0) {
            perror("SRT proxy send upstream");
        }
    }

    void schedule(packet value) {
        const auto base = next_base_time_.value_or(clock_type::now());
        next_base_time_ = base + std::chrono::duration_cast<clock_type::duration>(
            std::chrono::duration<double, std::milli>(nominal_interval_ms_));

        auto due = base;
        if (jitter_target_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (last_due_ && due < *last_due_) {
            due = *last_due_;
        }

        scheduled_.emplace(due, std::move(value));
        last_due_ = due;
    }

    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            jitter_target_protocol::srt, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    void flush_ready() {
        const auto now = clock_type::now();
        while (!scheduled_.empty() && scheduled_.begin()->first <= now) {
            send_downstream(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
        }
    }

    void forward_from_upstream() {
        packet value(65536);
        sockaddr_storage source{};
        socklen_t source_length = sizeof(source);
        const auto received = ::recvfrom(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<sockaddr*>(&source),
            &source_length);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        sender_ = source;
        sender_length_ = source_length;
        has_sender_ = true;

        if (is_data_packet(value)) {
            impairment_.submit(std::move(value));
        } else {
            send_downstream(value);
        }
    }

    void forward_from_downstream() {
        packet value(65536);
        const auto received = ::recvfrom(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            nullptr,
            nullptr);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        send_upstream(value);
    }

    void run() {
        while (!stopping_) {
            pollfd fds[2]{};
            fds[0].fd = upstream_fd_;
            fds[0].events = POLLIN;
            fds[1].fd = downstream_fd_;
            fds[1].events = POLLIN;

            const int result = ::poll(fds, 2, 10);
            if (result > 0) {
                if ((fds[0].revents & POLLIN) != 0) {
                    forward_from_upstream();
                }
                if ((fds[1].revents & POLLIN) != 0) {
                    forward_from_downstream();
                }
            }

            flush_ready();
        }
    }

    int upstream_fd_{-1};
    int downstream_fd_{-1};
    sockaddr_in destination_{};
    sockaddr_storage sender_{};
    socklen_t sender_length_{0};
    bool has_sender_{false};
    std::uint16_t local_port_{0};
    double jitter_ms_{0.0};
    double jitter_target_ms_{0.0};
    double nominal_interval_ms_{0.0};
    std::mt19937 rng_;
    std::uniform_real_distribution<double> jitter_distribution_;
    bool target_high_phase_{false};
    std::optional<clock_type::time_point> next_base_time_;
    std::optional<clock_type::time_point> last_due_;
    std::multimap<clock_type::time_point, packet> scheduled_;
    packet_impairer impairment_;
    std::atomic<bool> stopping_{false};
    std::thread worker_;
};
#endif

