    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            jitter_target_protocol::srt, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    void flush_ready() {
        const auto now = clock_type::now();
        while (!scheduled_.empty() && scheduled_.begin()->first <= now) {
            send_downstream(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
