    void forward_from_upstream() {
        packet value(65536);
        sockaddr_storage source{};
        socklen_t source_length = sizeof(source);
        const auto received = ::recvfrom(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<sockaddr*>(&source),
            &source_length);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        sender_ = source;
        sender_length_ = source_length;
        has_sender_ = true;

        if (is_data_packet(value)) {
            impairment_.submit(std::move(value));
        } else {
            send_downstream(value);
        }
    }

    void forward_from_downstream() {
        packet value(65536);
        const auto received = ::recvfrom(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            nullptr,
            nullptr);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        send_upstream(value);
    }

    void run() {
        while (!stopping_) {
            pollfd fds[2]{};
            fds[0].fd = upstream_fd_;
            fds[0].events = POLLIN;
            fds[1].fd = downstream_fd_;
            fds[1].events = POLLIN;

