void run_srt(const options& opt) {
#ifndef ENABLE_SRT
    std::cerr << "SRT disabled. Build with -DENABLE_SRT and link libsrt.\n";
    (void)opt;
#else
    SRTSOCKET sock = srt_create_socket();
    if (sock == SRT_INVALID_SOCK) {
        std::cerr << "srt_create_socket failed\n";
        return;
    }

    std::unique_ptr<srt_impairment_proxy> proxy;
    std::string connect_dst = opt.dst;
    std::uint16_t connect_port = opt.port;
    if (impairment_enabled(opt)) {
        proxy = std::make_unique<srt_impairment_proxy>(opt);
        if (!proxy->open(opt.dst, opt.port)) {
            srt_close(sock);
            return;
        }
        proxy->start();
        connect_dst = "127.0.0.1";
        connect_port = proxy->local_port();
    }

    int yes = 1;
    srt_setsockopt(sock, 0, SRTO_SENDER, &yes, sizeof(yes));

    sockaddr_in sa{};
    sa.sin_family = AF_INET;
    sa.sin_port = htons(connect_port);

    if (::inet_pton(AF_INET, connect_dst.c_str(), &sa.sin_addr) != 1) {
        std::cerr << "invalid ip: " << connect_dst << "\n";
        srt_close(sock);
        if (proxy) proxy->stop();
        return;
    }

    if (srt_connect(sock, reinterpret_cast<sockaddr*>(&sa), sizeof(sa)) == SRT_ERROR) {
        std::cerr << "srt_connect failed: " << srt_getlasterror_str() << "\n";
        srt_close(sock);
        if (proxy) proxy->stop();
        return;
    }

    const double packets_per_sec =
        static_cast<double>(opt.bitrate_bps) /
        static_cast<double>(opt.payload_size * 8);

    if (packets_per_sec <= 0.0) {
        std::cerr << "invalid SRT packets_per_sec\n";
        srt_close(sock);
        if (proxy) proxy->stop();
        return;
    }

    const auto interval = std::chrono::nanoseconds(
        static_cast<long long>(1'000'000'000.0 / packets_per_sec));

    std::vector<char> payload(opt.payload_size, 0);

    std::cerr
        << "SRT: " << opt.dst << ":" << opt.port
        << " bitrate=" << opt.bitrate_bps
        << " payload=" << opt.payload_size
        << " pps=" << packets_per_sec
        << "\n";

    if (proxy) {
        std::cerr << "SRT impairment proxy: 127.0.0.1:" << proxy->local_port()
                  << " -> " << opt.dst << ":" << opt.port << "\n";
    }
    print_impairment(opt);

    auto next = clock_type::now();
    std::uint64_t counter = 0;

    while (!g_stop) {
        for (std::size_t i = 0; i < payload.size(); ++i) {
            payload[i] = static_cast<char>((counter + i) & 0xff);
        }

        const int ret = srt_sendmsg(
            sock,
            payload.data(),
            static_cast<int>(payload.size()),
            -1,
            0);

        if (ret == SRT_ERROR) {
            std::cerr << "srt_sendmsg failed: " << srt_getlasterror_str() << "\n";
            break;
        }

        ++counter;

        next += interval;
        std::this_thread::sleep_until(next);
    }

    srt_close(sock);
    if (proxy) proxy->stop();
#endif
}

