    std::uint32_t ssrc{0};
    std::uint8_t pt{33};
    std::uint16_t seq{0};
    std::uint32_t timestamp{0};

    std::size_t payload_size{1316};
    bool mpegts_payload{false};

    std::string mcast_if{};
    int mcast_ttl{1};
    int mcast_loop{1};

    bool open(const std::string& ip, std::uint16_t port) {
        fd = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (fd < 0) {
            perror("socket");
            return false;
        }

        std::memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);

        if (::inet_pton(AF_INET, ip.c_str(), &addr.sin_addr) != 1) {
            std::cerr << "invalid ip: " << ip << "\n";
            return false;
        }

        if (is_ipv4_multicast_addr(addr.sin_addr)) {
            if (!configure_multicast()) {
                return false;
            }
        }

        return true;
    }

    bool configure_multicast() {
        const unsigned char ttl = static_cast<unsigned char>(mcast_ttl);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
            perror("setsockopt IP_MULTICAST_TTL");
            return false;
        }

        const unsigned char loop = static_cast<unsigned char>(mcast_loop != 0);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_LOOP, &loop, sizeof(loop)) < 0) {
            perror("setsockopt IP_MULTICAST_LOOP");
            return false;
        }

        if (!mcast_if.empty()) {
            in_addr local_if{};
            if (::inet_pton(AF_INET, mcast_if.c_str(), &local_if) != 1) {
                std::cerr << "invalid --mcast-if: " << mcast_if << "\n";
                return false;
            }

            if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_IF, &local_if, sizeof(local_if)) < 0) {
                perror("setsockopt IP_MULTICAST_IF");
                return false;
            }
        }

        return true;
    }

    void close() {
        if (fd >= 0) {
            ::close(fd);
            fd = -1;
        }
    }

    void make_packet(std::vector<std::uint8_t>& out) {
        out.resize(12 + payload_size);

        out[0] = 0x80;          // V=2, P=0, X=0, CC=0
        out[1] = pt & 0x7f;     // M=0, PT

        put_u16_be(&out[2], seq);
        put_u32_be(&out[4], timestamp);
        put_u32_be(&out[8], ssrc);

        auto* payload = out.data() + 12;

        if (mpegts_payload) {
            // MPEG-TS風ダミーpayload。
            // 188 byteごとにsync byte 0x47を置くだけなので、再生可能なTSではない。
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = (i % 188 == 0)
                    ? 0x47
                    : static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        } else {
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        }
    }

    void send_packet(const std::vector<std::uint8_t>& packet) {
        const auto n = ::sendto(
            fd,
            packet.data(),
            packet.size(),
            0,
            reinterpret_cast<const sockaddr*>(&addr),
            sizeof(addr));

        if (n < 0) {
            perror("sendto");
        }
    }
};

struct fec_state {
    std::vector<std::uint8_t> row_xor;
    std::vector<std::uint8_t> col_xor;

    std::uint32_t row_count{0};
    std::uint32_t col_count{0};
};

void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
    constexpr std::size_t header_size = 12;

    if (rtp_packet.size() < header_size) {
        return;
    }

    const std::size_t payload_len = rtp_packet.size() - header_size;

    if (acc.empty()) {
        acc.assign(payload_len, 0);
    }

    const auto n = std::min(acc.size(), payload_len);
    for (std::size_t i = 0; i < n; ++i) {
        acc[i] ^= rtp_packet[header_size + i];
    }
}

void make_fec_payload_packet(
    udp_rtp_sender& fec_sender,
    const std::vector<std::uint8_t>& xor_payload_data,
    std::vector<std::uint8_t>& out)
{
    fec_sender.payload_size = xor_payload_data.size();
    fec_sender.make_packet(out);

    if (!xor_payload_data.empty()) {
        std::memcpy(out.data() + 12, xor_payload_data.data(), xor_payload_data.size());
    }
}

void apply_mcast_options(udp_rtp_sender& s, const options& opt) {
    s.mcast_if = opt.mcast_if;
    s.mcast_ttl = opt.mcast_ttl;
    s.mcast_loop = opt.mcast_loop;
}

using packet = std::vector<std::uint8_t>;
using packet_submitter = std::function<void(packet)>;

class packet_impairer {
public:
    packet_impairer(const options& opt, packet_submitter submit)
        : loss_rate_(opt.loss_rate)
        , duplicate_rate_(opt.duplicate_rate)
        , reorder_rate_(opt.reorder_rate)
        , submit_(std::move(submit))
        , rng_(opt.seed ? *opt.seed : std::random_device{}()) {}

    void submit(packet value) {
        const bool drop = hit(loss_rate_);
        const bool duplicate = hit(duplicate_rate_);
        const bool reorder = hit(reorder_rate_);

        if (delayed_) {
            if (!drop) {
                submit_with_duplicate(std::move(value), duplicate);
            }
            submit_(std::move(*delayed_));
            delayed_.reset();
            return;
        }

        if (drop) {
            return;
        }

        if (reorder) {
            delayed_ = std::move(value);
            return;
        }

        submit_with_duplicate(std::move(value), duplicate);
    }

    void flush() {
        if (delayed_) {
            submit_(std::move(*delayed_));
            delayed_.reset();
        }
    }

private:
    bool hit(double rate) {
        return rate > 0.0 && distribution_(rng_) < rate;
    }

    void submit_with_duplicate(packet value, bool duplicate) {
        if (duplicate) {
            submit_(value);
        }
        submit_(std::move(value));
    }

    double loss_rate_{0.0};
    double duplicate_rate_{0.0};
    double reorder_rate_{0.0};
    packet_submitter submit_;
    std::mt19937 rng_;
