    std::uint32_t fec_col_ssrc{2002};

    // 簡易FEC用。厳密なRFC/SMPTE準拠ではない。
    std::uint32_t fec_l{4};
    std::uint32_t fec_d{4};

    // IPv4 multicast送信用オプション。
    // --dst が 224.0.0.0/4 の場合に適用される。
        << "  " << argv0 << " --proto rtp --port 5000 --bitrate 1000000 --fec --fec-row-port 5002 --fec-col-port 5004\n"
        << "  " << argv0 << " --proto srt --dst 127.0.0.1 --port 9000 --bitrate 1000000\n"
        << "\nOptions:\n"
