        << "  --pt <payload-type>\n"
        << "  --clock-rate <rate>\n"
        << "  --mpegts-payload 0|1\n"
        << "\nPacket impairment options (RTP/SRT data packets):\n"
        << "  --loss <rate>\n"
        << "  --duplicate <rate>\n"
