bool impairment_enabled/class packet_scheduler {
public:
    packet_scheduler(
        const options& opt,
        packet_submitter send,
        jitter_target_protocol target_protocol)
        : jitter_ms_(opt.jitter_ms)
        , jitter_target_ms_(opt.jitter_target_ms)
        , target_reorder_(jitter_target_reorders(opt))
        , target_protocol_(target_protocol)
        , send_(std::move(send))
        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , worker_([this] { run(); }) {}

    ~packet_scheduler() {
        stop();
    }

    packet_scheduler(const packet_scheduler&) = delete;
    packet_scheduler& operator=(const packet_scheduler&) = delete;

    void set_base_time(clock_type::time_point value) {
        base_time_ = value;
    }

    void submit(packet value) {
        auto due = base_time_.value_or(clock_type::now());
        if (jitter_target_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        // Random-delay mode and the default target mode retain packet order.
        // Target reorder mode intentionally lets an earlier due packet overtake it.
        if (!target_reorder_ && last_due_ && due < *last_due_) {
            due = *last_due_;
        }
        last_due_ = due;

        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopping_) {
                return;
            }
            scheduled_.emplace(std::make_pair(due, next_sequence_++), std::move(value));
        }
        wake_.notify_one();
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopping_) {
                return;
            }
            stopping_ = true;
            scheduled_.clear();
        }
        wake_.notify_one();
        if (worker_.joinable()) {
            worker_.join();
        }
    }

private:
    using schedule_key = std::pair<clock_type::time_point, std::uint64_t>;

    void run() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (!stopping_) {
            if (scheduled_.empty()) {
                wake_.wait(lock);
                continue;
            }

            const auto due = scheduled_.begin()->first.first;
            if (clock_type::now() < due) {
                wake_.wait_until(lock, due);
                continue;
            }

            packet value = std::move(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
            lock.unlock();
            send_(std::move(value));
            lock.lock();
        }
    }

    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            target_protocol_, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    double jitter_ms_{0.0};
    double jitter_target_ms_{0.0};
    bool target_reorder_{false};
    jitter_target_protocol target_protocol_{jitter_target_protocol::rtp};
    packet_submitter send_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> jitter_distribution_;
    bool target_high_phase_{false};
    std::optional<clock_type::time_point> base_time_;
    std::optional<clock_type::time_point> last_due_;
    std::mutex mutex_;
    std::condition_variable wake_;
    std::map<schedule_key, packet> scheduled_;
    std::uint64_t next_sequence_{0};
    bool stopping_{false};
    std::thread worker_;
};

