bool impairment_enabled(const options& opt) {
    return opt.loss_rate > 0.0 ||
           opt.duplicate_rate > 0.0 ||
           opt.reorder_rate > 0.0 ||
           opt.jitter_ms > 0.0 ||
           opt.jitter_target_ms > 0.0;
}

void print_impairment(const options& opt) {
    if (!impairment_enabled(opt)) {
        return;
    }

    std::cerr
        << "impairment: loss=" << opt.loss_rate
        << " duplicate=" << opt.duplicate_rate
        << " reorder=" << opt.reorder_rate
        << " jitter_ms=" << opt.jitter_ms
        << " jitter_target_ms=" << opt.jitter_target_ms;

    if (opt.seed) {
        std::cerr << " seed=" << *opt.seed;
    }

    std::cerr << "\n";
}

void run_rtp(const options& opt) {
    const double packets_per_sec =
        static_cast<double>(opt.bitrate_bps) /
        static_cast<double>(opt.payload_size * 8);

    if (packets_per_sec <= 0.0) {
        std::cerr << "invalid packets_per_sec\n";
        return;
    }

    const auto interval = std::chrono::nanoseconds(
        static_cast<long long>(1'000'000'000.0 / packets_per_sec));

