                opt.fec_l = static_cast<std::uint32_t>(std::stoul(v));
            } else if (a == "--fec-d") {
                const char* v = next("--fec-d");
                if (!v) return std::nullopt;
                opt.fec_d = static_cast<std::uint32_t>(std::stoul(v));
            } else if (a == "--mcast-if") {
                const char* v = next("--mcast-if");
                if (!v) return std::nullopt;
                opt.mcast_if = v;
            } else if (a == "--mcast-ttl") {
                const char* v = next("--mcast-ttl");
                if (!v) return std::nullopt;
                opt.mcast_ttl = std::stoi(v);
            } else if (a == "--mcast-loop") {
                const char* v = next("--mcast-loop");
                if (!v) return std::nullopt;
                opt.mcast_loop = std::stoi(v);
            } else if (a == "--help" || a == "-h") {
                return std::nullopt;
            } else {
                std::cerr << "unknown option: " << a << "\n";
                return std::nullopt;
            }
        }
    } catch (const std::exception& e) {
        std::cerr << "argument parse error: " << e.what() << "\n";
        return std::nullopt;
    }

    if (opt.payload_size == 0) {
        std::cerr << "--payload-size must be greater than 0\n";
        return std::nullopt;
    }

    if (opt.bitrate_bps == 0) {
        std::cerr << "--bitrate must be greater than 0\n";
        return std::nullopt;
    }

    if (opt.srt_streamid.size() > 512) {
        std::cerr << "--srt-streamid must be at most 512 bytes\n";
        return std::nullopt;
    }

    const auto valid_rate = [](double value) {
        return std::isfinite(value) && value >= 0.0 && value <= 1.0;
    };

    if (!valid_rate(opt.loss_rate) ||
        !valid_rate(opt.duplicate_rate) ||
        !valid_rate(opt.reorder_rate)) {
        std::cerr << "--loss, --duplicate, and --reorder must be rates in 0..1\n";
        return std::nullopt;
    }

    if (!std::isfinite(opt.jitter_ms) || opt.jitter_ms < 0.0 || opt.jitter_ms > 60000.0) {
        std::cerr << "--jitter-ms must be in 0..60000\n";
        return std::nullopt;
    }

    if (!std::isfinite(opt.jitter_target_ms) || opt.jitter_target_ms < 0.0 || opt.jitter_target_ms > 60000.0) {
        std::cerr << "--jitter-target-ms must be in 0..60000\n";
        return std::nullopt;
    }

    if (opt.jitter_ms > 0.0 && opt.jitter_target_ms > 0.0) {
        std::cerr << "--jitter-ms and --jitter-target-ms cannot be used together\n";
        return std::nullopt;
    }

    if (opt.target_mode == jitter_target_mode::reorder && opt.jitter_target_ms == 0.0) {
        std::cerr << "--jitter-target-mode reorder requires --jitter-target-ms\n";
        return std::nullopt;
    }

    const double ordered_target_limit_ms = ordered_jitter_target_limit_ms(opt);
    if (opt.jitter_target_ms > ordered_target_limit_ms &&
        opt.target_mode != jitter_target_mode::reorder) {
        std::cerr
            << "--jitter-target-ms " << opt.jitter_target_ms
            << " exceeds the ordered "
            << (opt.proto == proto_type::rtp ? "RTP" : "SRT")
            << " limit of " << ordered_target_limit_ms
            << " ms at the configured bitrate and payload size; "
               "use --jitter-target-mode reorder to permit data-packet reordering\n";
        return std::nullopt;
    }

    if (opt.fec_l == 0 || opt.fec_d == 0) {
        std::cerr << "--fec-l and --fec-d must be greater than 0\n";
        return std::nullopt;
    }

    if (opt.mcast_ttl < 0 || opt.mcast_ttl > 255) {
        std::cerr << "--mcast-ttl must be 0..255\n";
        return std::nullopt;
    }
};

void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
    constexpr std::size_t header_size = 12;

    if (rtp_packet.size() < header_size) {
        return;
    }

    const std::size_t payload_len = rtp_packet.size() - header_size;

    if (acc.empty()) {
        acc.assign(payload_len, 0);
    }

    const auto n = std::min(acc.size(), payload_len);
    for (std::size_t i = 0; i < n; ++i) {
        acc[i] ^= rtp_packet[header_size + i];
    }
}

void make_fec_payload_packet(
    udp_rtp_sender& fec_sender,
    const std::vector<std::uint8_t>& xor_payload_data,
    std::vector<std::uint8_t>& out)
{
    fec_sender.payload_size = xor_payload_data.size();
    fec_sender.make_packet(out);

    if (!xor_payload_data.empty()) {
        std::memcpy(out.data() + 12, xor_payload_data.data(), xor_payload_data.size());
    }
}

