void put_u16_be(std::uint8_t* p, std::uint16_t v) {
    p[0] = static_cast<std::uint8_t>((v >> 8) & 0xff);
    p[1] = static_cast<std::uint8_t>(v & 0xff);
}

void put_u32_be(std::uint8_t* p, std::uint32_t v) {
    p[0] = static_cast<std::uint8_t>((v >> 24) & 0xff);
    p[1] = static_cast<std::uint8_t>((v >> 16) & 0xff);
    p[2] = static_cast<std::uint8_t>((v >> 8) & 0xff);
    p[3] = static_cast<std::uint8_t>(v & 0xff);
}

bool is_ipv4_multicast_addr(const in_addr& addr) {
    const std::uint32_t a = ntohl(addr.s_addr);
    return a >= 0xE0000000u && a <= 0xEFFFFFFFu; // 224.0.0.0/4
}

enum class proto_type {
    rtp,
    srt,
};

enum class jitter_target_mode {
    ordered,
    reorder,
};

struct options {
    proto_type proto{proto_type::rtp};

    std::string dst{"127.0.0.1"};
    std::uint16_t port{5000};
    std::uint32_t bitrate_bps{1'000'000};
    std::size_t payload_size{188 * 7};

    std::uint32_t ssrc{1001};
    std::uint8_t pt{33};
    std::uint32_t clock_rate{90000};
    std::string srt_streamid{};

    bool mpegts_payload{true};

    double loss_rate{0.0};
    double duplicate_rate{0.0};
    double reorder_rate{0.0};
    double jitter_ms{0.0};
    double jitter_target_ms{0.0};
    jitter_target_mode target_mode{jitter_target_mode::ordered};
    std::optional<std::uint32_t> seed{};

    bool fec{false};
    std::uint16_t fec_row_port{5002};
    std::uint16_t fec_col_port{5004};
    std::uint8_t fec_pt{96};
    std::uint32_t fec_row_ssrc{2001};
    std::uint32_t fec_col_ssrc{2002};

    // 簡易FEC用。厳密なRFC/SMPTE準拠ではない。
    std::uint32_t fec_l{4};
    std::uint32_t fec_d{4};

    // IPv4 multicast送信用オプション。
    // --dst が 224.0.0.0/4 の場合に適用される。
    std::string mcast_if{};
    int mcast_ttl{1};
    int mcast_loop{1};
};

const char* jitter_target_mode_name(jitter_target_mode mode) {
    return mode == jitter_target_mode::ordered ? "ordered" : "reorder";
}

double nominal_packet_interval_ms(const options& opt) {
    return 1000.0 * static_cast<double>(opt.payload_size) * 8.0 /
        static_cast<double>(opt.bitrate_bps);
}

double ordered_jitter_target_limit_ms(const options& opt) {
    const double interval_ms = nominal_packet_interval_ms(opt);
    return opt.proto == proto_type::rtp ? interval_ms : interval_ms * 2.0;
}

bool jitter_target_reorders(const options& opt) {
    return opt.jitter_target_ms > 0.0 && opt.target_mode == jitter_target_mode::reorder;
}

std::uint16_t parse_u16(const char* s, const char* name) {
    const auto v = std::stoul(s);
    if (v > 65535) {
        throw std::runtime_error(std::string(name) + " out of range: " + s);
    }
    return static_cast<std::uint16_t>(v);
    return static_cast<std::uint16_t>(v);
}

std::uint8_t parse_u8(const char* s, const char* name) {
    const auto v = std::stoul(s);
    if (v > 255) {
        throw std::runtime_error(std::string(name) + " out of range: " + s);
    }
    return static_cast<std::uint8_t>(v);
}

std::uint32_t parse_u32(const char* s, const char* name) {
    const auto v = std::stoull(s);
    if (v > 0xffffffffULL) {
        throw std::runtime_error(std::string(name) + " out of range: " + s);
    }
    return static_cast<std::uint32_t>(v);
}

