bool parse_impairment(const std::string& value, options& opt, std::string& error) {
    std::vector<std::string> items;
    std::size_t begin = 0;
    while (begin <= value.size()) {
        const std::size_t end = value.find(''','', begin);
        items.push_back(value.substr(begin, end == std::string::npos ? end : end - begin));
        if (end == std::string::npos) break;
        begin = end + 1;
    }

    if (items.empty() || items.front().empty()) {
        error = "--impair requires a type";
        return false;
    }

    std::map<std::string, std::string> fields;
    for (std::size_t i = 1; i < items.size(); ++i) {
        const std::size_t equals = items[i].find('''=''');
        if (equals == std::string::npos || equals == 0 || equals + 1 == items[i].size()) {
            error = "--impair fields must be key=value";
            return false;
        }
        const auto [it, inserted] = fields.emplace(items[i].substr(0, equals), items[i].substr(equals + 1));
        if (!inserted) {
            error = "--impair contains a repeated field: " + it->first;
            return false;
        }
    }

    const auto field = [&fields](const char* name) -> const std::string* {
        const auto it = fields.find(name);
        return it == fields.end() ? nullptr : &it->second;
    };
    const auto only_fields = [&fields, &error](std::initializer_list<const char*> allowed) {
        for (const auto& [name, ignored] : fields) {
            (void)ignored;
            if (std::find(allowed.begin(), allowed.end(), name) == allowed.end()) {
                error = "--impair field is not valid for this type/mode: " + name;
                return false;
            }
        }
        return true;
    };

    const std::string& type = items.front();
    if (type == "loss" || type == "duplicate" || type == "reorder") {
        const std::string* mode = field("mode");
        if (!mode) {
            error = "--impair " + type + " requires mode=rate or mode=periodic";
            return false;
        }

        counted_impairment parsed;
        if (*mode == "rate") {
            const std::string* rate = field("rate");
            if (!rate || !only_fields({"mode", "rate"})) {
                if (!rate && error.empty()) error = "--impair " + type + ",mode=rate requires rate";
                return false;
            }
            parsed.mode = occurrence_mode::rate;
            parsed.rate = parse_finite_double(*rate, "rate");
        } else if (*mode == "periodic") {
            const std::string* period = field("period");
            const std::string* count = field("count");
            if (!period || !count || !only_fields({"mode", "period", "count"})) {
                if ((!period || !count) && error.empty()) error = "--impair " + type + ",mode=periodic requires period and count";
                return false;
            }
            parsed.mode = occurrence_mode::periodic;
            if (!parse_period(*period, parsed.periodic, error)) return false;
            parsed.periodic.count = parse_positive_u64(*count, "count");
        } else {
            error = "--impair " + type + " mode must be rate or periodic";
            return false;
        }

        counted_impairment* target = type == "loss" ? &opt.loss :
            (type == "duplicate" ? &opt.duplicate : &opt.reorder);
        return set_counted_impairment(*target, std::move(parsed), type.c_str(), error);
    }

    if (type == "jitter") {
        const std::string* mode = field("mode");
        if (!mode) {
            error = "--impair jitter requires mode=random or mode=target";
            return false;
        }

        jitter_impairment parsed;
        if (*mode == "random") {
            const std::string* max_ms = field("max-ms");
            if (!max_ms || !only_fields({"mode", "max-ms"})) {
                if (!max_ms && error.empty()) error = "--impair jitter,mode=random requires max-ms";
                return false;
            }
            parsed.mode = jitter_mode::random;
            parsed.max_ms = parse_finite_double(*max_ms, "max-ms");
        } else if (*mode == "target") {
            const std::string* target_ms = field("target-ms");
            const std::string* target_mode = field("target-mode");
            if (!target_ms || !only_fields({"mode", "target-ms", "target-mode"})) {
                if (!target_ms && error.empty()) error = "--impair jitter,mode=target requires target-ms";
                return false;
            }
            parsed.mode = jitter_mode::target;
            parsed.target_ms = parse_finite_double(*target_ms, "target-ms");
            if (target_mode && *target_mode == "reorder") {
                parsed.target_mode = jitter_target_mode::reorder;
            } else if (target_mode && *target_mode != "ordered") {
                error = "jitter target-mode must be ordered or reorder";
                return false;
            }
        } else {
            error = "--impair jitter mode must be random or target";
            return false;
        }
        return set_jitter_impairment(opt.jitter, std::move(parsed), error);
    }

    error = "--impair type must be loss, duplicate, reorder, or jitter";
    return false;
}

