command:
perl -0pi -e 's@bool impairment_enabled\(const options& opt\) \{.*?
\}

void run_rtp@bool counted_impairment_enabled(const counted_impairment& value) {
    return value.mode != occurrence_mode::none;
}

std::string describe_counted_impairment(const counted_impairment& value, bool reorder) {
    if (value.mode == occurrence_mode::none) {
        return "off";
    }
    std::ostringstream out;
    if (value.mode == occurrence_mode::rate) {
        out << "rate=" << value.rate;
        return out.str();
    }

    if (value.periodic.basis == period_basis::packets) {
        out << "periodic=" << value.periodic.packet_period << "p";
    } else {
        out << "periodic="
            << std::chrono::duration<double, std::milli>(value.periodic.time_period).count()
            << "ms";
    }
    out << ",count=" << value.periodic.count;
    if (reorder) {
        out << "pairs";
    }
    return out.str();
}

bool impairment_enabled(const options& opt) {
    return counted_impairment_enabled(opt.loss) ||
           counted_impairment_enabled(opt.duplicate) ||
           counted_impairment_enabled(opt.reorder) ||
           opt.jitter.mode != jitter_mode::none;
}

void print_impairment(const options& opt) {
    if (!impairment_enabled(opt)) {
        return;
    }

    std::cerr
        << "impairment: loss=" << describe_counted_impairment(opt.loss, false)
        << " duplicate=" << describe_counted_impairment(opt.duplicate, false)
        << " reorder=" << describe_counted_impairment(opt.reorder, true);

    if (opt.jitter.mode == jitter_mode::random) {
        std::cerr << " jitter=random,max-ms=" << opt.jitter.max_ms;
    } else if (opt.jitter.mode == jitter_mode::target) {
        std::cerr << " jitter=target,target-ms=" << opt.jitter.target_ms
                  << ",target-mode=" << jitter_target_mode_name(opt.jitter.target_mode);
    }
    if (opt.seed) {
        std::cerr << " seed=" << *opt.seed;
    }

    std::cerr << "\n";
}

void print_impairment_warnings(const options& opt) {
    const double interval_ms = nominal_packet_interval_ms(opt);
    const bool has_counted_errors =
        counted_impairment_enabled(opt.loss) ||
        counted_impairment_enabled(opt.duplicate) ||
        counted_impairment_enabled(opt.reorder);
    const bool has_rate_error =
        opt.loss.mode == occurrence_mode::rate ||
        opt.duplicate.mode == occurrence_mode::rate ||
        opt.reorder.mode == occurrence_mode::rate;

    if (opt.uses_legacy_impairment_options) {
        std::cerr << "warning: legacy impairment aliases are deprecated; use --impair type,mode=...,key=value\n";
    }

    const auto warn_time_period_capacity = [&opt](
        const counted_impairment& value, bool reorder, const char* type) {
        if (value.mode != occurrence_mode::periodic ||
            value.periodic.basis != period_basis::time) {
            return;
        }
        const double expected_packets =
            static_cast<double>(opt.bitrate_bps) / static_cast<double>(opt.payload_size * 8) *
            std::chrono::duration<double>(value.periodic.time_period).count();
        const std::uint64_t required = reorder ? value.periodic.count * 2 : value.periodic.count;
        if (expected_packets < static_cast<double>(required)) {
            std::cerr
                << "warning: --impair " << type << " time period has about "
                << expected_packets << " nominal packets but requires " << required
                << "; a window can contain fewer errors than count.\n";
        }
    };
    warn_time_period_capacity(opt.loss, false, "loss");
    warn_time_period_capacity(opt.duplicate, false, "duplicate");
    warn_time_period_capacity(opt.reorder, true, "reorder");

    if (opt.jitter.mode == jitter_mode::random && opt.jitter.max_ms > interval_ms) {
        std::cerr
            << "warning: jitter random max-ms " << opt.jitter.max_ms
            << " exceeds the nominal packet interval " << interval_ms
            << " ms; ordered delivery clamps some delays, so the configured maximum delay may not be observed.\n";
    }

    if (jitter_target_reorders(opt)) {
        std::cerr
            << "warning: jitter target-mode=reorder permits "
            << (opt.proto == proto_type::rtp ? "RTP" : "SRT")
            << " data packets to arrive out of order; target-ms is best effort and includes reordering effects.\n";
    }

    if (opt.jitter.mode == jitter_mode::target && has_counted_errors) {
        std::cerr
            << "warning: loss, duplicate, or reorder injection changes the jitter estimator input; jitter target-ms is not guaranteed with these impairments.\n";
    }

    if (has_rate_error) {
        std::cerr
            << "warning: rate-mode impairments are independent probabilities; short captures need not match their configured rates.\n";
    }

    const int active_counted = static_cast<int>(counted_impairment_enabled(opt.loss)) +
        static_cast<int>(counted_impairment_enabled(opt.duplicate)) +
        static_cast<int>(counted_impairment_enabled(opt.reorder));
    if (active_counted > 1) {
        std::cerr
            << "warning: combined loss, duplicate, and reorder act on the same source packets; observed counts can differ from individual settings.\n";
    }

    if (opt.proto == proto_type::rtp && opt.jitter.mode == jitter_mode::target &&
        opt.clock_rate > 0 && opt.jitter.target_ms < 1000.0 / opt.clock_rate) {
        std::cerr
            << "warning: jitter target-ms " << opt.jitter.target_ms
            << " is below the RTP timestamp resolution " << (1000.0 / opt.clock_rate)
            << " ms; the target cannot be represented exactly.\n";
    }

    if (opt.proto == proto_type::srt && opt.jitter.mode == jitter_mode::target &&
        opt.jitter.target_ms < 10.0) {
        std::cerr
            << "warning: SRT impairment scheduling polls at up to 10 ms; small jitter targets can be dominated by scheduler latency.\n";
    }

    if (opt.proto == proto_type::srt && has_counted_errors) {
        std::cerr
            << "warning: SRT retransmission and receiver buffering can change observed loss, reorder, and jitter from the UDP proxy settings.\n";
    }
}

