using packet = std::vector<std::uint8_t>;
using packet_submitter = std::function<void(packet)>;

class packet_impairer {
public:
    packet_impairer(const options& opt, packet_submitter submit)
        : loss_rate_(opt.loss_rate)
        , duplicate_rate_(opt.duplicate_rate)
        , reorder_rate_(opt.reorder_rate)
        , submit_(std::move(submit))
        , rng_(opt.seed ? *opt.seed : std::random_device{}()) {}

    void submit(packet value) {
        const bool drop = hit(loss_rate_);
        const bool duplicate = hit(duplicate_rate_);
        const bool reorder = hit(reorder_rate_);

        if (delayed_) {
            if (!drop) {
                submit_with_duplicate(std::move(value), duplicate);
            }
            submit_(std::move(*delayed_));
            delayed_.reset();
            return;
        }

        if (drop) {
            return;
        }

        if (reorder) {
            delayed_ = std::move(value);
            return;
        }

        submit_with_duplicate(std::move(value), duplicate);
    }

    void flush() {
        if (delayed_) {
            submit_(std::move(*delayed_));
            delayed_.reset();
        }
    }

private:
    bool hit(double rate) {
        return rate > 0.0 && distribution_(rng_) < rate;
    }

    void submit_with_duplicate(packet value, bool duplicate) {
        if (duplicate) {
            submit_(value);
        }
        submit_(std::move(value));
    }

    double loss_rate_{0.0};
    double duplicate_rate_{0.0};
    double reorder_rate_{0.0};
    packet_submitter submit_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::optional<packet> delayed_;
};

