using packet = std::vector<std::uint8_t>;
using packet_submitter = std::function<void(packet)>;

class occurrence_selector {
public:
    occurrence_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool hit(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const bool selected = packets_in_period_ >
                settings_.periodic.packet_period - settings_.periodic.count;
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            selected_in_window_ = 0;
        }
        if (selected_in_window_ >= settings_.periodic.count) {
            return false;
        }
        ++selected_in_window_;
        return true;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t selected_in_window_{0};
};

class reorder_selector {
public:
    reorder_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool starts_pair(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const std::uint64_t pair_packets = settings_.periodic.count * 2;
            const std::uint64_t first_pair_packet =
                settings_.periodic.packet_period - pair_packets + 1;
            const bool selected = packets_in_period_ >= first_pair_packet &&
                ((packets_in_period_ - first_pair_packet) % 2 == 0);
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            packets_in_window_ = 0;
        }
        const std::uint64_t pair_packets = settings_.periodic.count * 2;
        const bool selected = packets_in_window_ < pair_packets &&
            (packets_in_window_ % 2 == 0);
        if (packets_in_window_ < pair_packets) {
            ++packets_in_window_;
        }
        return selected;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t packets_in_window_{0};
};

class packet_impairer {
public:
    packet_impairer(const options& opt, packet_submitter submit)
        : loss_(opt.loss, impairment_seed(opt, 0x243f6a88U))
        , duplicate_(opt.duplicate, impairment_seed(opt, 0x85a308d3U))
        , reorder_(opt.reorder, impairment_seed(opt, 0x13198a2eU))
        , submit_(std::move(submit)) {}

    void submit(packet value) {
        const auto now = clock_type::now();
        const bool drop = loss_.hit(now);
        const bool duplicate = duplicate_.hit(now);
        const bool reorder = reorder_.starts_pair(now);

        if (delayed_) {
            if (!drop) {
                submit_with_duplicate(std::move(value), duplicate);
            }
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
            return;
        }

        if (drop) {
            return;
        }

        if (reorder) {
            delayed_ = delayed_packet{std::move(value), duplicate};
            return;
        }

        submit_with_duplicate(std::move(value), duplicate);
    }

    void flush() {
        if (delayed_) {
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
        }
    }

private:
    static std::uint32_t impairment_seed(const options& opt, std::uint32_t salt) {
        return opt.seed ? (*opt.seed ^ salt) : std::random_device{}();
    }

    struct delayed_packet {
        packet value;
        bool duplicate{false};
    };

    void submit_with_duplicate(packet value, bool duplicate) {
        if (duplicate) {
            submit_(value);
        }
        submit_(std::move(value));
    }

    occurrence_selector loss_;
    occurrence_selector duplicate_;
    reorder_selector reorder_;
    packet_submitter submit_;
    std::optional<delayed_packet> delayed_;
};

