bool counted_impairment_enabled(const counted_impairment& value) {
    return value.mode == occurrence_mode::periodic ||
           (value.mode == occurrence_mode::rate && value.rate > 0.0);
}

bool jitter_impairment_enabled(const jitter_impairment& value) {
    return (value.mode == jitter_mode::random && value.max_ms > 0.0) ||
           (value.mode == jitter_mode::target && value.target_ms > 0.0);
}

std::string describe_counted_impairment(const counted_impairment& value, bool reorder) {
    if (value.mode == occurrence_mode::none) {
        return "off";
    }
    std::ostringstream out;
    if (value.mode == occurrence_mode::rate) {
        out << "rate=" << value.rate;
        return out.str();
    }

    if (value.periodic.basis == period_basis::packets) {
        out << "periodic=" << value.periodic.packet_period << "p";
    } else {
        out << "periodic="
            << std::chrono::duration<double, std::milli>(value.periodic.time_period).count()
            << "ms";
    }
    out << ",count=" << value.periodic.count;
    if (reorder) {
        out << "pairs";
    }
    return out.str();
        static_cast<double>(opt.bitrate_bps);
