    const auto interval = std::chrono::nanoseconds(
        static_cast<long long>(1'000'000'000.0 / packets_per_sec));

    const std::uint32_t ts_step =
        static_cast<std::uint32_t>(
            static_cast<double>(opt.clock_rate) / packets_per_sec);

    udp_rtp_sender media;
    media.ssrc = opt.ssrc;
    media.pt = opt.pt;
    media.payload_size = opt.payload_size;
    media.mpegts_payload = opt.mpegts_payload;
    apply_mcast_options(media, opt);

    if (!media.open(opt.dst, opt.port)) {
        return;
    }

    udp_rtp_sender fec_row;
    udp_rtp_sender fec_col;

    if (opt.fec) {
        fec_row.ssrc = opt.fec_row_ssrc;
        fec_row.pt = opt.fec_pt;
        fec_row.payload_size = opt.payload_size;
        fec_row.mpegts_payload = false;
        apply_mcast_options(fec_row, opt);

        fec_col.ssrc = opt.fec_col_ssrc;
        fec_col.pt = opt.fec_pt;
        fec_col.payload_size = opt.payload_size;
        fec_col.mpegts_payload = false;
        apply_mcast_options(fec_col, opt);

        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
            media.close();
            return;
        }

        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
            media.close();
            fec_row.close();
            return;
        }
    }

    std::cerr
        << "RTP media: " << opt.dst << ":" << opt.port
        << " ssrc=" << opt.ssrc
        << " pt=" << static_cast<int>(opt.pt)
        << " bitrate=" << opt.bitrate_bps
        << " payload=" << opt.payload_size
        << " pps=" << packets_per_sec
        << " ts_step=" << ts_step
        << "\n";

    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
        std::cerr
            << "multicast: ttl=" << opt.mcast_ttl
            << " loop=" << opt.mcast_loop;

        if (!opt.mcast_if.empty()) {
            std::cerr << " if=" << opt.mcast_if;
        } else {
            std::cerr << " if=<route-default>";
        }

        std::cerr << "\n";
    }

    print_impairment(opt);
    print_impairment_warnings(opt);

    if (opt.fec) {
        std::cerr
            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
            << " ssrc=" << opt.fec_row_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " L=" << opt.fec_l
            << "\n";

        std::cerr
            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
            << " ssrc=" << opt.fec_col_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " D=" << opt.fec_d
            << "\n";
    }

    packet_scheduler scheduler(
        opt,
        [&media](packet value) { media.send_packet(value); },
        jitter_target_protocol::rtp);
    packet_impairer impairment(opt, [&scheduler](packet value) {
        scheduler.submit(std::move(value));
    });

    packet media_packet;

    fec_state fec;
    std::vector<std::uint8_t> fec_packet;

    auto next = clock_type::now();

    while (!g_stop) {
        media.make_packet(media_packet);

        if (opt.fec) {
            xor_payload(fec.row_xor, media_packet);
            xor_payload(fec.col_xor, media_packet);

            ++fec.row_count;
            ++fec.col_count;

            if (fec.row_count >= opt.fec_l) {
                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
                fec_row.send_packet(fec_packet);

                ++fec_row.seq;
                fec_row.timestamp += ts_step * opt.fec_l;

                fec.row_xor.clear();
                fec.row_count = 0;
            }

            if (fec.col_count >= opt.fec_d) {
                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
                fec_col.send_packet(fec_packet);

                ++fec_col.seq;
                fec_col.timestamp += ts_step * opt.fec_d;

                fec.col_xor.clear();
                fec.col_count = 0;
            }
        }

        scheduler.set_base_time(next);
        impairment.submit(media_packet);

        ++media.seq;
        media.timestamp += ts_step;

        next += interval;
        std::this_thread::sleep_until(next);
    }

    impairment.flush();
    scheduler.stop();
    media.close();

    if (opt.fec) {
        fec_row.close();
        fec_col.close();
    }
}

